// Cyrus R5 delivery orchestrator: the HOST SEAM and the result types. Cyrus reaches a server ONLY through these small
// injectable interfaces (file access, installer, restart, health probe, managed-plugin refs, pack hosting); Nxeon
// implements them in the worker (worker/cyrus-delivery.ts), tests implement them with fakes, the node-2 real run
// with a disposable Test Flight server. Plain JSON results (for the admin read model and a future UI).
import type { TxnFs, RollbackReport } from "./journal";
import type { ReadOnlyServerFs } from "../inventory/types";
import type { InventoryReport } from "../inventory/types";
import type { MemberPlacer } from "../modpack/install";
import type { PackStore } from "../packhost/types";
import type { StoredCreature } from "../creature/deliver";

export type Env = Record<string, string | undefined>;

/** Everything one revision of a Cyrus mod delivers, resolved and verified by the host BEFORE the server is touched. */
export type ModRelease = {
  projectId: string;
  revisionId: string;
  modBuildId?: string | null;
  namespace: string;
  /** The Minecraft version the mod was built for (managed-plugin pins are per family). */
  mcVersion: string;
  label: string;
  plugin: { pluginName: string; jarName: string; sha256: string; bytes: Buffer } | null;
  /** The mod's resource pack (Pack Loader entry role "main"): zip to publish, or an already hosted url. */
  pack: { sha1: string; sha256?: string; zip?: Buffer; url?: string; prompt: string; required: boolean } | null;
  datapacks: { name: string; zip: Buffer; sha256: string; apply: "reload" | "restart"; worldgen?: { dimensions: string[] } }[];
  /** BetterModel creatures: the compiled .bbmodel files are re-derived (and checked) by the orchestrator. */
  creatures: StoredCreature[];
};

/** What a delivery left on the server (the on-server record at DELIVERY_RECORD_DIR/<projectId>.json). */
export type DeliveryRecord = {
  schema: 1;
  projectId: string;
  revisionId: string;
  namespace: string;
  mcVersion: string;
  pluginName: string | null;
  jar: { target: string; sha256: string } | null;
  datapacks: { name: string; target: string; sha256: string; apply: "reload" | "restart"; dimensions?: string[] }[];
  models: { target: string; sha256: string }[];
  packLoaderIds: string[];
  managed: string[];
  deliveredAt: string;
};

export type HealthExpect = {
  /** Plugin names that must be enabled. */
  plugins: string[];
  /** Plugin names that must NOT be enabled any more (uninstall). */
  pluginsGone?: string[];
  /** Datapack ids as `datapack list` shows them (file/<name>.zip). */
  datapacks: string[];
  /** World generation changed: the server must actually reach "Done" after the restart. */
  worldgen: boolean;
};
export type HealthReport = {
  /** The health probe ran against a real server process (false = simulated: never a pass). */
  real: boolean;
  cameUp: boolean;
  answered: boolean;
  pluginsEnabled: string[];
  errorLines: string[];
  datapacksLoaded: string[];
  evidence: string[];
};
export type HealthVerdict = { ok: boolean; problems: string[]; report: HealthReport | null };

/** One open server for the length of a delivery (worker job, under the per-server lock). */
export interface ServerSession {
  fs: TxnFs;
  base: string;
  levelName: string;
  /** The server's Minecraft version (from the host's own record or the inventory). */
  mcVersion: string | null;
  restart(): Promise<{ ok: true } | { ok: false; error: string }>;
  /** One console command (RCON); absent = the host cannot run commands (reloads then wait for the next restart). */
  console?(command: string): Promise<{ ok: true; reply: string } | { ok: false; error: string }>;
  /** Probe after a restart / reload. */
  health(expect: HealthExpect): Promise<HealthReport>;
  /** Error lines the server already had before this delivery (so only NEW ones fail the health check). */
  baselineErrors?(): Promise<string[]>;
  close?(): void;
}

export interface ManagedPort {
  /** Install / add a ref. `fs` is the delivery's journaled file access: the installer must write only through it. */
  ensure(a: { serverId: string; key: string; mcVersion: string; dependent: string; fs: TxnFs }): Promise<{ ok: true; action: "installed" | "upgraded" | "ref_added" | "already"; pluginName: string } | { ok: false; error: string }>;
  release(a: { serverId: string; key: string; dependent: string; fs: TxnFs }): Promise<{ ok: true; action: "removed" | "ref_dropped" | "not_held" } | { ok: false; error: string }>;
  /** Opaque snapshot of this server's managed-plugin refs (database rows), restored on rollback. */
  snapshot(serverId: string): Promise<unknown>;
  restore(serverId: string, snap: unknown): Promise<{ ok: true } | { ok: false; error: string }>;
}

export interface JarPort {
  /** Place (or replace) the mod's plugin jar; must write only through `fs`. Returns the absolute target path. */
  install(a: { serverId: string; fs: TxnFs; base: string; release: ModRelease; previous: DeliveryRecord | null }): Promise<{ ok: true; target: string } | { ok: false; error: string }>;
  remove(a: { serverId: string; fs: TxnFs; base: string; record: DeliveryRecord }): Promise<{ ok: true } | { ok: false; error: string }>;
}

export interface DeliveryHost {
  open(serverId: string): Promise<ServerSession>;
  /** Read-only view for the inventory (default: the session's fs). */
  readOnly?(session: ServerSession): ReadOnlyServerFs;
  managed: ManagedPort;
  jar: JarPort;
  /** Pack hosting (immutable, content-addressed). Absent = packs cannot be hosted here: the pack part is skipped. */
  packs?: { publish(zip: Buffer, sha1: string): Promise<{ url: string }>; store?: PackStore };
  /** Mod Packs: the member placer to use with the journaled fs (Nxeon: the Mods engine placer). */
  modpackPlacer?(fs: TxnFs, session: ServerSession, packId: string): MemberPlacer;
  /** Third-party Mod Pack files. */
  fetchArtifact?: (f: import("../modpack/manifest").NxPackFile) => Promise<Buffer>;
  /** BetterModel config template (default: lib/cyrus/managed/bettermodel-config.yml). */
  betterModelConfig?: () => string;
  env?: Env;
  now?: () => Date;
  /** Fault injection (tests only): throw at the named step. */
  fault?: (step: DeliveryStep) => void;
}

export const DELIVERY_STEPS = ["open", "recover_check", "preflight", "managed", "host_pack", "pack_config", "place", "apply", "health", "handoff", "record", "commit"] as const;
export type DeliveryStep = (typeof DELIVERY_STEPS)[number];
export type StepResult = { step: DeliveryStep | "rollback" | "rollback_restart" | "rollback_health"; status: "ok" | "failed" | "skipped"; ms: number; detail: string };

export type ConflictSummary = { blocking: { id: string; class: string; message: string }[]; warnings: { id: string; class: string; severity: string; message: string }[]; notChecked: string[] };

export type DeliveryOutcome =
  | "delivered" | "updated" | "uninstalled" | "unchanged" | "pending_restart"
  | "refused" | "rolled_back" | "rollback_incomplete";

export type DeliveryResult = {
  ok: boolean;
  outcome: DeliveryOutcome;
  op: "install" | "update" | "uninstall" | "modpack_install" | "modpack_uninstall";
  serverId: string;
  subject: { projectId?: string; revisionId?: string; packId?: string; versionId?: string };
  steps: StepResult[];
  /** Why it failed / was refused (customer-safe text). */
  error?: string;
  failedStep?: DeliveryStep;
  conflicts?: ConflictSummary;
  apply?: { mode: "restart" | "reload" | "none"; reasons: string[]; restarted: boolean; reloaded: boolean };
  health?: HealthVerdict;
  rollback?: RollbackReport & { refs: "restored" | "failed" | "unchanged"; restarted: boolean; health: HealthVerdict | null };
  notes: string[];
  record?: DeliveryRecord | null;
  /** Uninstall: dimension world folders KEPT on the server (listed for an admin cleanup action). */
  keptWorldFolders?: string[];
  journalId?: string;
  startedAt: string;
  finishedAt: string;
};

export type { TxnFs, RollbackReport, InventoryReport };
// Cyrus R5 delivery: the pure rules (flags, apply semantics, health expectations, record paths). No I/O.
import { DATAPACK_DELIVERY_FLAG } from "../datapack/deliver";
import { worldgenOn } from "../datapack/route";
import { MANAGED_REAL_FLAG } from "../managed/installer";
import { CREATURES_FLAG } from "../creature/deliver";
import { MODPACK_REAL_FLAG } from "../modpack/engine-placer";
import type { DeliveryRecord, Env, HealthExpect, HealthReport, HealthVerdict } from "./types";
import { cyrusConfig } from "../config";

/** Master switch for the whole orchestrator (worker). OFF by default: nothing opens a server. */
export const DELIVERY_FLAG = "CYRUS_DELIVERY";
export const DELIVERY_RECORD_DIR = `${cyrusConfig().guest.stateDir}/deliveries`;
export const PACK_LOADER_KEY = "nxeon-pack-loader";
export const PACK_LOADER_PLUGIN = "NxeonPackLoader";
export const BETTERMODEL_KEY = "bettermodel";
export const BETTERMODEL_PLUGIN = "BetterModel";
/** Paths whose writes are never journaled: the Mods engine's and the Mod Pack unit's own rotating backup caches. */
export const JOURNAL_PASSTHROUGH = [cyrusConfig().guest.modsBackupDir, `${cyrusConfig().guest.stateDir}/modpack-backups`];

export type Switches = { delivery: boolean; managed: boolean; datapacks: boolean; worldgen: boolean; creatures: boolean; modpacks: boolean };
export function switches(env: Env): Switches {
  return {
    delivery: env[DELIVERY_FLAG] === "1",
    managed: env[MANAGED_REAL_FLAG] === "1",
    datapacks: env[DATAPACK_DELIVERY_FLAG] === "1",
    worldgen: worldgenOn(env),
    creatures: env[MANAGED_REAL_FLAG] === "1" && env[CREATURES_FLAG] === "1",
    modpacks: env[MODPACK_REAL_FLAG] === "1",
  };
}

export const recordPath = (projectId: string) => {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(projectId)) throw new Error("bad project id");
  return `${DELIVERY_RECORD_DIR}/${projectId}.json`;
};
export const datapackFile = (namespace: string, name: string) => `nxeon-${namespace}-${name}.zip`;
export const datapackId = (file: string) => `file/${file}`;
export const dependentFor = (projectId: string) => `project:${projectId}`;
export const packDependent = (packId: string) => `mod:${packId}`;

export function readRecord(raw: Buffer | null): DeliveryRecord | null {
  if (!raw) return null;
  try {
    const r = JSON.parse(raw.toString("utf8")) as DeliveryRecord;
    return r && r.schema === 1 && typeof r.projectId === "string" && Array.isArray(r.datapacks) && Array.isArray(r.models) ? r : null;
  } catch { return null; }
}

export type ApplyInput = {
  jarChanged: boolean;
  managedChanged: boolean;
  datapacks: { changed: boolean; apply: "reload" | "restart"; worldgen: boolean }[];
  modelsChanged: boolean;
  managedConfigChanged: boolean;
  loaderChanged: boolean;
};
export type ApplyPlan = { mode: "restart" | "reload" | "none"; reasons: string[]; consoleAfter: string[]; requireCameUp: boolean; handoff: boolean };

/**
 * How the change takes effect (VERIFIED behaviour, docs R0-R4): plugin jars (ours or managed) load only at start ->
 * restart; registry content (enchantments) and world generation load only at start -> restart (worldgen: the server
 * must reach Done, a broken pack stops it); BetterModel models load at start and its pack hand-off must follow that
 * restart; reloadable data packs -> `minecraft:reload`; a Pack Loader config change alone is picked up by the plugin
 * (`nxpacks reload`, or its file watch within ~10 s).
 */
export function planApply(i: ApplyInput): ApplyPlan {
  const reasons: string[] = [];
  if (i.jarChanged) reasons.push("a plugin jar changed (plugins load at server start)");
  if (i.managedChanged) reasons.push("an Nxeon-managed plugin was installed, upgraded or removed");
  const wg = i.datapacks.some((d) => d.changed && d.worldgen);
  if (wg) reasons.push("world generation changed (loads only at server start)");
  if (i.datapacks.some((d) => d.changed && d.apply === "restart" && !d.worldgen)) reasons.push("a data pack adds registry content (loads only at server start)");
  if (i.modelsChanged || i.managedConfigChanged) reasons.push("animated creature models changed (BetterModel loads them at start)");
  const restart = reasons.length > 0;
  const reload = !restart && i.datapacks.some((d) => d.changed);
  const consoleAfter: string[] = [];
  if (i.loaderChanged) consoleAfter.push("nxpacks reload");
  return {
    mode: restart ? "restart" : reload ? "reload" : "none",
    reasons: restart ? reasons : reload ? ["data pack content is reloadable (minecraft:reload)"] : i.loaderChanged ? ["only the Pack Loader config changed (the plugin reloads it)"] : [],
    consoleAfter, requireCameUp: wg || restart, handoff: i.modelsChanged || i.managedConfigChanged,
  };
}

/** Judge a health report against the expectations. A simulated probe is never a pass. */
export function judgeHealth(expect: HealthExpect, r: HealthReport | null, baseline: string[] = []): HealthVerdict {
  const problems: string[] = [];
  if (!r) return { ok: false, problems: ["the health probe did not run"], report: null };
  if (!r.real) problems.push("the health probe was simulated (no real server): not verified");
  if (!r.cameUp) problems.push(expect.worldgen ? "the server did not come up after the restart (world generation stops a server that cannot load it)" : "the server did not come up");
  if (r.cameUp && !r.answered) problems.push("the server came up but does not answer commands");
  const enabled = new Set(r.pluginsEnabled.map((p) => p.toLowerCase()));
  for (const p of expect.plugins) if (!enabled.has(p.toLowerCase())) problems.push(`plugin ${p} is not enabled`);
  for (const p of expect.pluginsGone ?? []) if (enabled.has(p.toLowerCase())) problems.push(`plugin ${p} is still enabled`);
  const norm = (l: string) => l.replace(/^\[[^\]]*\]\s*/, "").replace(/\d{2}:\d{2}:\d{2}/g, "").trim();
  const base = new Set(baseline.map(norm));
  const fresh = r.errorLines.filter((l) => !base.has(norm(l)));
  if (fresh.length) problems.push(`new error lines in the server log: ${fresh.slice(0, 3).join(" | ").slice(0, 400)}`);
  const loaded = new Set(r.datapacksLoaded);
  for (const d of expect.datapacks) if (!loaded.has(d)) problems.push(`data pack ${d} is not loaded`);
  return { ok: problems.length === 0, problems, report: r };
}

/** Dimension world folders a removed worldgen pack leaves (KEPT on uninstall: players' builds live there). */
export function dimensionFolders(base: string, level: string, dims: string[]): string[] {
  return [...new Set(dims)].filter((d) => /^[a-z0-9_.-]+:[a-z0-9_./-]+$/.test(d)).map((d) => { const [ns, path] = d.split(":"); return `${base}/${level}/dimensions/${ns}/${path}`; }).sort();
}
// Cyrus R5 admin visibility (READ-ONLY, no UI): a typed read model over what is already stored -
//   deliveries:  GAME_MOD_SYNC jobs with the cyrusDelivery payload discriminator (their result: steps, rollback, health)
//   flights:     ModBuild.cyrus.testFlight (the Test Flight gate's per-check result)
//   engines:     ModBuild.cyrus.engineRelease (the engine release record)
//   passRates:   aggregate counts per Minecraft version from stored flights, for a future public pass-rate page
//                (only real, completed flights count; "not run" is counted apart and never as a pass).
// Injectable db (host seam): only `job.findMany` and `modBuild.findMany` are used.
import { readStoredFlight, type StoredFlight } from "../testflight/gate";
import { readEngineRelease, type EngineRelease } from "../engine-core/release";
import { opsTelemetryView, type AggregateRow, type OpsTelemetryView } from "../telemetry/aggregate";
import { windowOf } from "../telemetry/collect";

export type DeliveryRow = {
  jobId: string; serverId: string | null; createdAt: string; jobStatus: string;
  op: string | null; outcome: string | null; ok: boolean | null; failedStep: string | null; error: string | null;
  steps: { step: string; status: string; ms: number; detail: string }[];
  rollback: { ok: boolean; restored: number; removed: number; mismatches: string[]; refs: string; restarted: boolean; healthOk: boolean | null } | null;
  healthOk: boolean | null; notes: string[]; subject: Record<string, string>;
};
export type FlightRow = { buildId: string; mcVersion: string; state: StoredFlight["state"]; verdict: StoredFlight["verdict"]; label: string | null; checks: StoredFlight["checks"]; reason: string | null; at: string };
export type EngineRow = { buildId: string; mcVersion: string; engineId: string; recordedAt: string; prompt: string | null; scanner: string | null; image: string | null; unknown: string[] };
export type PassRateRow = { version: string; flown: number; passed: number; failed: number; incomplete: number; notRun: number; passRate: number | null };
export type CyrusOpsReport = { generatedAt: string; deliveries: DeliveryRow[]; flights: FlightRow[]; engines: EngineRow[]; passRates: PassRateRow[]; health?: OpsTelemetryView };

type JobLike = { id: string; serverId: string | null; createdAt: Date; status: string; payload: unknown };
type BuildLike = { id: string; mcVersion: string; cyrus: unknown };
export type AdminDb = {
  job: { findMany(args: unknown): Promise<JobLike[]> };
  modBuild: { findMany(args: unknown): Promise<BuildLike[]> };
};

const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

export function deliveryRow(j: JobLike): DeliveryRow {
  const p = obj(j.payload);
  const r = obj(obj(p.result).cyrusDelivery);
  const rb = r.rollback ? obj(r.rollback) : null;
  return {
    jobId: j.id, serverId: j.serverId, createdAt: j.createdAt.toISOString(), jobStatus: j.status,
    op: typeof r.op === "string" ? r.op : (obj(p.cyrusDelivery).op as string) ?? null,
    outcome: typeof r.outcome === "string" ? r.outcome : null, ok: typeof r.ok === "boolean" ? r.ok : null,
    failedStep: typeof r.failedStep === "string" ? r.failedStep : null, error: typeof r.error === "string" ? r.error : null,
    steps: Array.isArray(r.steps) ? (r.steps as DeliveryRow["steps"]).slice(0, 40) : [],
    rollback: rb ? { ok: rb.ok === true, restored: Number(rb.restored ?? 0), removed: Number(rb.removed ?? 0), mismatches: Array.isArray(rb.mismatches) ? (rb.mismatches as string[]).slice(0, 10) : [], refs: String(rb.refs ?? "unchanged"), restarted: rb.restarted === true, healthOk: rb.health ? obj(rb.health).ok === true : null } : null,
    healthOk: r.health ? obj(r.health).ok === true : null,
    notes: Array.isArray(r.notes) ? (r.notes as string[]).slice(0, 12) : [],
    subject: Object.fromEntries(Object.entries(obj(r.subject)).filter(([, v]) => typeof v === "string")) as Record<string, string>,
  };
}

/** Aggregate stored flights per version (pure). Only completed flights (state done) count towards the rate. */
export function passRates(flights: { version: string; state: StoredFlight["state"]; verdict: StoredFlight["verdict"] }[]): PassRateRow[] {
  const m = new Map<string, PassRateRow>();
  for (const f of flights) {
    const r = m.get(f.version) ?? { version: f.version, flown: 0, passed: 0, failed: 0, incomplete: 0, notRun: 0, passRate: null };
    if (f.state === "done") { r.flown++; if (f.verdict === "passed") r.passed++; else if (f.verdict === "failed") r.failed++; else r.incomplete++; }
    else if (f.state === "not_run" || f.state === "gave_up") r.notRun++;
    m.set(f.version, r);
  }
  return [...m.values()].map((r) => ({ ...r, passRate: r.flown ? Math.round((r.passed / r.flown) * 1000) / 1000 : null })).sort((a, b) => b.version.localeCompare(a.version, undefined, { numeric: true }));
}

/**
 * `telemetry` (optional; nothing passes it yet): the mod health telemetry aggregates (k-anonymous rows only are shown,
 * see lib/cyrus/telemetry/aggregate.ts). Without it the report has no `health` key.
 */
export async function cyrusOpsReport(db: AdminDb, opts: { limit?: number; now?: Date; telemetry?: { enabled: boolean; rows: () => Promise<AggregateRow[]> } } = {}): Promise<CyrusOpsReport> {
  const limit = Math.min(500, Math.max(1, opts.limit ?? 100));
  const jobs = await db.job.findMany({ where: { type: "GAME_MOD_SYNC", payload: { path: ["cyrusDelivery", "v"], equals: 1 } }, orderBy: { createdAt: "desc" }, take: limit, select: { id: true, serverId: true, createdAt: true, status: true, payload: true } });
  const builds = await db.modBuild.findMany({ where: { status: "succeeded" }, orderBy: { finishedAt: "desc" }, take: limit * 5, select: { id: true, mcVersion: true, cyrus: true } });
  const flights: FlightRow[] = [];
  const engines: EngineRow[] = [];
  for (const b of builds) {
    const c = obj(b.cyrus);
    const f = readStoredFlight(c.testFlight);
    if (f) flights.push({ buildId: b.id, mcVersion: b.mcVersion, state: f.state, verdict: f.verdict, label: f.label, checks: f.checks, reason: f.reason ?? null, at: f.at });
    const e: EngineRelease | null = readEngineRelease(c.engineRelease);
    if (e) engines.push({ buildId: b.id, mcVersion: b.mcVersion, engineId: e.id, recordedAt: e.recordedAt, prompt: e.prompts.base ?? null, scanner: e.scanner?.sha256?.slice(0, 12) ?? null, image: e.service?.image ?? null, unknown: e.unknown });
  }
  return {
    generatedAt: (opts.now ?? new Date()).toISOString(),
    deliveries: jobs.map(deliveryRow),
    flights: flights.slice(0, limit), engines: engines.slice(0, limit),
    passRates: passRates(flights.map((f) => ({ version: f.mcVersion, state: f.state, verdict: f.verdict }))),
    ...(opts.telemetry ? { health: opsTelemetryView(await opts.telemetry.rows(), { enabled: opts.telemetry.enabled, window: windowOf(opts.now ?? new Date()) }) } : {}),
  };
}
// Cyrus R5: assemble a ModRelease (what one mod version delivers) from a finished build's stored facts. Pure: the
// caller (worker/cyrus-delivery.ts, the Test Flight gate) reads the jar bytes and the data pack asset rows and passes
// them in. Every part is re-verified here (jar sha256, data pack rebuilt deterministically to the recorded sha256).
import { createHash } from "node:crypto";
import { rebuildForDelivery } from "../datapack/deliver";
import { readBuildAssets } from "../assets/sync";
import type { ModRelease } from "./types";
import type { StoredCreature } from "../creature/deliver";

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

export type BuildFacts = { id: string; mcVersion: string; pluginName: string | null; jarName: string | null; jarSha256: string | null; result: unknown; rootBuildId: string | null };
/** A CyrusProjectAsset row of kind "datapack" (provenance: spec, version, packSha256, worldgen). */
export type DatapackAssetRow = { assetKey: string; provenance: unknown };

export function releaseFromBuild(b: BuildFacts, jar: Buffer | null, opts: { project: { id: string; namespace: string } | null; datapackAssets?: DatapackAssetRow[]; label?: string }): { ok: true; release: ModRelease; notes: string[] } | { ok: false; error: string } {
  const notes: string[] = [];
  if (!jar || !b.jarName || !b.pluginName) return { ok: false, error: "the build has no stored plugin jar" };
  if (b.jarSha256 && sha256(jar) !== b.jarSha256) return { ok: false, error: "the stored plugin jar does not match its checksum" };
  const a = readBuildAssets(b.result);
  const project = opts.project ?? (a ? { id: a.projectId, namespace: a.namespace } : null);
  if (!project) return { ok: false, error: "the build has no Cyrus project (namespace), so it cannot be delivered by Cyrus" };
  const pack = a?.status === "ready" && a.loader ? { sha1: a.loader.sha1, url: a.loader.url, prompt: a.loader.prompt, required: a.loader.required, ...(a.pack ? { sha256: a.pack.sha256 } : {}) } : null;
  if (a && a.status === "unhosted") notes.push("the custom resource pack is not hosted here, so it is not delivered");
  const datapacks: ModRelease["datapacks"] = [];
  for (const row of a?.datapacks ?? []) {
    const asset = (opts.datapackAssets ?? []).find((x) => x.assetKey === row.name || (x.provenance as { packSha256?: string } | null)?.packSha256 === row.sha256);
    if (!asset) { notes.push(`data pack ${row.name}: its stored spec was not found, so it is not delivered`); continue; }
    const rb = rebuildForDelivery((asset.provenance ?? {}) as Record<string, unknown>, project.namespace);
    if (!rb.ok) { notes.push(`data pack ${row.name}: ${rb.error}`); continue; }
    if (rb.sha256 !== row.sha256) { notes.push(`data pack ${row.name}: rebuilt bytes differ from the build's record`); continue; }
    datapacks.push({ name: rb.name, zip: rb.zip, sha256: rb.sha256, apply: rb.apply, ...(rb.worldgen ? { worldgen: rb.worldgen } : {}) });
  }
  const creatures = ((a?.creatures ?? []) as unknown as StoredCreature[]).map((c) => ({ name: c.name, key: c.key, spec: c.spec, bbmodelSha256: c.bbmodelSha256 }));
  return {
    ok: true, notes,
    release: {
      projectId: project.id, revisionId: a?.revisionId ?? `build:${b.id}`, modBuildId: b.id, namespace: project.namespace, mcVersion: b.mcVersion, label: opts.label ?? b.pluginName,
      plugin: { pluginName: b.pluginName, jarName: b.jarName, sha256: sha256(jar), bytes: jar }, pack, datapacks, creatures,
    },
  };
}

/**
 * Cyrus R5 delivery job (worker side): Nxeon's implementation of the orchestrator's host seam
 * (lib/cyrus/delivery/types.ts DeliveryHost) and the job entry point.
 *
 * Wiring (the only one, and only as far as is clearly safe): a GAME_MOD_SYNC job whose payload carries
 * `{ cyrusDelivery: { v: 1, op: "deliver" | "uninstall", buildId?, projectId?, serverModId?, restartPolicy? } }`
 * (a payload DISCRIMINATOR on an existing job type: no new enum value, no new table) is handed to
 * `cyrusDeliveryJob` instead of the normal mod reconcile. Nothing enqueues such a job yet (no route, no UI), and the
 * handler refuses unless CYRUS_DELIVERY=1. Each part is still behind its own flag (CYRUS_MANAGED_PLUGINS_REAL,
 * CYRUS_DATAPACK_DELIVERY_REAL (+ CYRUS_WORLDGEN), CYRUS_CREATURES) and the Mods engine's ENABLE_REAL_GAMEMODS.
 * The GAME_MOD_SYNC job already holds the per-server lock (one job per server at a time).
 *
 * The result (steps, rollback, health, notes) is stored on the job's payload.result.cyrusDelivery: the admin read
 * model (lib/cyrus/delivery/admin.ts) lists recent deliveries from there.
 *
 * SANDBOX: the server is the fake guest dir; a "restart" cannot boot anything there, so the health probe reports
 * `real: false` and a delivery that needs a restart is honestly rolled back (use restartPolicy "next_restart" there).
 */
