export async function deliverModPack(serverId: string, built: { manifest: unknown; archive: Map<string, Buffer> }, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
  const env = host.env ?? process.env;
  const v = validateNxPack(built.manifest);
  const packId = v.ok ? v.pack.packId : "unknown";
  return transaction({
    serverId, op: "modpack_install", subject: { packId, versionId: v.ok ? v.pack.versionId : undefined }, host, label: `modpack-${packId}`, opts,
    prepare: async (session, steps) => timed({ steps, host }, "preflight", async () => {
      if (!v.ok) throw new Refusal("preflight", `invalid Mod Pack: ${v.errors[0]?.message ?? "?"}`);
      if (!switches(env).modpacks) throw new Refusal("preflight", "Mod Pack installs are switched off (CYRUS_MODPACK_INSTALL_REAL is not 1); nothing was changed");
      if (!host.modpackPlacer) throw new Refusal("preflight", "this host cannot place Mod Pack members");
      const raw = await session.fs.readFile(`${session.base}/${LOADER_CONFIG_PATH}`, 1024 * 1024);
      if (raw) { let j: unknown; try { j = JSON.parse(raw.toString("utf8")); } catch { throw new Refusal("preflight", "the server's packs.json is not valid JSON; nothing was changed"); } if (!validateLoaderConfig(j).ok) throw new Refusal("preflight", "the server's packs.json is invalid; nothing was changed"); }
      // the plugin names the health check expects: read from the embedded (Cyrus-built) jars themselves
      const names: string[] = [];
      const cands: ModEntry[] = [];
      for (const f of v.pack.embedded) {
        if (f.role !== "plugin") continue;
        const b = built.archive.get(f.embedded);
        if (!b) continue;
        const file = f.path.slice(f.path.lastIndexOf("/") + 1);
        const n = inspectJar(file, f.path, b, { bytecode: false }).descriptor?.name;
        if (n) names.push(n);
        cands.push(candidateJar(file, b, { id: `candidate:${f.member}`, cyrus: null }));
      }
      // re-check against what the server runs NOW (the builder checked an inventory taken at build time);
      // files the pack itself already owns (its unit record) are not conflicts with itself
      const unit = await session.fs.readFile(`${cyrusConfig().guest.stateDir}/modpacks/${v.pack.packId}.json`, 4 * 1024 * 1024).catch(() => null);
      const owned = new Set<string>(((): string[] => { try { return (JSON.parse(unit?.toString("utf8") ?? "{}").files ?? []).map((x: { path: string }) => x.path.slice(session.base.length + 1)); } catch { return []; } })());
      const inv = await scanServer(host.readOnly?.(session) ?? session.fs, { base: session.base });
      const { mods, ctx: cctx } = inventoryEntries(inv, { exclude: (p) => owned.has(p) || [...owned].some((o) => o.endsWith(`/${p}`) || p.endsWith(o)) });
      const rep = detectConflicts([...cands, ...mods], { ...cctx, modPack: true });
      const ids = new Set(cands.map((c) => c.id));
      const conflicts = summarize(rep, (f) => f.items.some((i) => ids.has(i.mod)) && f.items.some((i) => !ids.has(i.mod)));
      if (conflicts.blocking.length) throw new Refusal("preflight", `blocked by ${conflicts.blocking.length} conflict(s) with what is already on the server: ${conflicts.blocking.map((b) => b.message).join(" | ").slice(0, 500)}; nothing was changed`, conflicts);
      return { conflicts, body: (t: Txn) => modpackBody(t, v.pack.packId, v.pack.resourcePacks.packs.length > 0, (fs) => installModPackUnit({ manifest: built.manifest, archive: built.archive, base: session.base, levelName: session.levelName, deps: { fs, placer: host.modpackPlacer!(fs, session, packId), fetch: host.fetchArtifact, publish: host.packs ? (zip, s) => host.packs!.publish(zip, s) : undefined } }), names) };
    }, () => "manifest valid"),
  });
}

export async function uninstallModPack(serverId: string, packId: string, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
  const env = host.env ?? process.env;
  return transaction({
    serverId, op: "modpack_uninstall", subject: { packId }, host, label: `modpack-${packId}-uninstall`, opts,
    prepare: async (_session, steps) => timed({ steps, host }, "preflight", async () => {
      if (!/^mp_[A-Za-z0-9]{12}$/.test(packId)) throw new Refusal("preflight", "bad pack id");
      if (!switches(env).modpacks) throw new Refusal("preflight", "Mod Pack installs are switched off (CYRUS_MODPACK_INSTALL_REAL is not 1); nothing was changed");
      if (!host.modpackPlacer) throw new Refusal("preflight", "this host cannot place Mod Pack members");
      return { body: (t: Txn) => modpackBody(t, packId, false, (fs) => uninstallModPackUnit({ packId, base: t.session.base, deps: { fs, placer: host.modpackPlacer!(fs, t.session, packId) } }), [], true) };
    }, () => "ok"),
  });
}

async function modpackBody(t: Txn, packId: string, needsLoader: boolean, run: (fs: JournalFs) => Promise<UnitResult>, pluginNames: string[], uninstall = false): Promise<BodyOut> {
  const dep = packDependent(packId);
  let managedChanged = false;
  const expect: string[] = [];
  if (needsLoader) {
    await timed(t, "managed", async () => {
      t.refsTouched = true;
      const e = await t.host.managed.ensure({ serverId: t.serverId, key: PACK_LOADER_KEY, mcVersion: t.session.mcVersion ?? "", dependent: dep, fs: t.jfs });
      if (!e.ok) throw new Error(e.error);
      managedChanged = e.action === "installed" || e.action === "upgraded";
      expect.push(e.pluginName);
      return e.action;
    }, (v) => v);
  } else skip(t, "managed", "no resource packs");
  const unit = await timed(t, "place", async () => {
    const u = await run(t.jfs);
    if (!u.ok) throw new Error(`Mod Pack ${u.step}: ${u.error}`);
    return u;
  }, (u) => `${u.ok ? u.action : ""}: ${u.ok ? u.changed.slice(0, 6).join(", ") : ""}`);
  if (uninstall) {
    await timed(t, "managed", async () => { t.refsTouched = true; const r = await t.host.managed.release({ serverId: t.serverId, key: PACK_LOADER_KEY, dependent: dep, fs: t.jfs }); if (!r.ok) throw new Error(r.error); if (r.action === "removed") managedChanged = true; return r.action; }, (v) => v);
  }
  const u = unit as Extract<UnitResult, { ok: true }>;
  const datapacks = (u.record?.files ?? []).filter((f) => f.path.includes("/datapacks/")).map((f) => datapackId(f.path.slice(f.path.lastIndexOf("/") + 1)));
  // A Mod Pack's data packs may carry registry content or world generation the unit cannot tell apart: treated as
  // restart content (conservative), and the server must come up after it.
  const changed = u.action !== "unchanged";
  return {
    apply: { jarChanged: u.restartRequired, managedChanged, datapacks: datapacks.map(() => ({ changed, apply: "restart" as const, worldgen: false })), modelsChanged: false, managedConfigChanged: false, loaderChanged: needsLoader && changed },
    record: null, outcome: uninstall ? "uninstalled" : u.action === "updated" ? "updated" : "delivered", unchanged: !changed && !managedChanged,
    expect: { plugins: uninstall ? [] : [...expect, ...pluginNames], datapacks: uninstall ? [] : datapacks, worldgen: false },
  };
}

// The interface a future Mod Pack UI / worker job uses (R2). One injectable HOST SEAM: Cyrus never imports Nxeon to
// reach a server, a download, pack hosting or Test Flight; Nxeon (today) or a standalone host API (later) implements
// `CompositionHost`. Mod Packs and conflict checks are NOT plan-gated, so the host needs no plan or user lookup here.
