const JDK_PREFIXES = ["java.", "javax.crypto", "javax.net", "javax.security", "javax.xml", "javax.naming", "javax.script", "javax.tools", "javax.management", "javax.sql", "javax.imageio", "javax.swing", "javax.sound", "javax.print", "javax.lang.model", "javax.annotation.processing", "jdk.", "sun.", "com.sun.", "org.w3c.dom", "org.xml.sax", "org.ietf.jgss"];

