        ok: false, outcome: incomplete ? "rollback_incomplete" : "rolled_back", failedStep, error: errMsg(e), conflicts: prep.conflicts ?? out?.conflicts,
        apply: plan ? { mode: plan.mode, reasons: plan.reasons, restarted: t.restartAttempted, reloaded: t.reloaded } : undefined, health, rollback: rb, record: null, journalId: jfs.id,
      });
    }
  } finally { session.close?.(); }
}

/** Undo: files (journal), refs (database), then restart / reload again if the change already reached the server. */
async function rollback(t: Txn, plan: ApplyPlan | null): Promise<RollbackReport & { refs: "restored" | "failed" | "unchanged"; restarted: boolean; health: HealthVerdict | null }> {
  const t0 = Date.now();
  const files = await t.jfs.rollback();
  let refs: "restored" | "failed" | "unchanged" = "unchanged";
  if (t.refsTouched) {
    const r = await t.host.managed.restore(t.serverId, t.refsSnap).catch((e) => ({ ok: false as const, error: errMsg(e) }));
    refs = r.ok ? "restored" : "failed";
    if (!r.ok) files.mismatches.push(`managed plugin refs: ${r.error}`);
  }
  t.steps.push({ step: "rollback", status: files.ok && refs !== "failed" ? "ok" : "failed", ms: Date.now() - t0, detail: `${files.restored} restored, ${files.removed} removed${files.mismatches.length ? `; MISMATCHES: ${files.mismatches.slice(0, 3).join(" | ")}` : ""}; refs ${refs}` });
  let restarted = false;
  let health: HealthVerdict | null = null;
  if (t.restartAttempted) {
    const t1 = Date.now();
    const r = await t.session.restart().catch((e) => ({ ok: false as const, error: errMsg(e) }));
    restarted = r.ok;
    t.steps.push({ step: "rollback_restart", status: r.ok ? "ok" : "failed", ms: Date.now() - t1, detail: r.ok ? "restarted on the previous state" : `restart after rollback failed: ${(r as { error: string }).error}` });
    const t2 = Date.now();
    const rep = r.ok ? await t.session.health({ plugins: [], datapacks: [], worldgen: false }).catch(() => null) : null;
    health = judgeHealth({ plugins: [], datapacks: [], worldgen: false }, rep, t.baseline);
    health.problems = health.problems.filter((p) => !p.startsWith("new error lines")); // the previous state's own log is not ours to judge
    health.ok = health.problems.length === 0;
    t.steps.push({ step: "rollback_health", status: health.ok ? "ok" : "failed", ms: Date.now() - t2, detail: health.ok ? "the server came up on the previous state" : health.problems.join("; ").slice(0, 400) });
  } else if (t.reloaded && t.session.console) {
    await t.session.console(RELOAD_COMMAND).catch(() => null);
  }
  void plan;
  return { ...files, refs, restarted, health };
}

// ------------------------------------------------------------------------------------------------ preflight helpers

function datapackCandidate(name: string, zip: Buffer, cyrus: ModEntry["cyrus"]): Promise<ModEntry> {
  const z = indexZip(zip);
  if (!z.ok) throw new Error(`data pack ${name}: ${z.error}`);
  const files = z.zip.entries.filter((e) => !e.dir && e.name.startsWith("data/")).map((e) => ({ path: e.name, read: () => { const r = readEntry(z.zip, e); return r.ok ? r.data : null; } }));
  const mm = z.zip.entries.find((e) => e.name === "pack.mcmeta");
  const mcmeta = mm ? (() => { const r = readEntry(z.zip, mm); return r.ok ? r.data : null; })() : null;
  return indexDatapack(name, "candidate", "zip", files, mcmeta).then((d) => datapackEntry(d, "candidate", { cyrus, changed: true }));
}

function summarize(rep: ReturnType<typeof detectConflicts>, involve: (f: { items: { mod: string }[] }) => boolean): ConflictSummary {
  const mine = rep.findings.filter(involve);
  return {
    blocking: mine.filter((f) => f.severity === "blocking").map((f) => ({ id: f.id, class: f.class, message: f.message })),
    warnings: mine.filter((f) => f.severity !== "blocking").map((f) => ({ id: f.id, class: f.class, severity: f.severity, message: f.message })).slice(0, 50),
    notChecked: rep.notChecked.slice(0, 30),
  };
}

function verifyRelease(r: ModRelease): string | null {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(r.projectId)) return "bad project id";
  if (!NS_RE.test(r.namespace)) return "bad namespace";
  if (r.plugin) {
    if (!/^[A-Za-z0-9._ -]{1,120}\.jar$/.test(r.plugin.jarName) || r.plugin.jarName.includes("/")) return "bad jar name";
    if (sha256(r.plugin.bytes) !== r.plugin.sha256) return "the plugin jar does not match its recorded sha256";
  }
  if (r.pack?.zip && sha1(r.pack.zip) !== r.pack.sha1) return "the resource pack does not match its recorded sha1";
  if (r.pack && !r.pack.zip && !(r.pack.url && /^https:\/\//.test(r.pack.url))) return "the resource pack has neither bytes nor an https URL";
  for (const d of r.datapacks) {
    if (!/^[a-z0-9_-]{1,40}$/.test(d.name)) return `bad data pack name ${d.name}`;
    if (sha256(d.zip) !== d.sha256) return `data pack ${d.name} does not match its recorded sha256`;
    if (d.worldgen && d.apply !== "restart") return `data pack ${d.name} has world generation and must be applied with a restart`;
  }
  return null;
}

// ------------------------------------------------------------------------------------------------ install / update

/** Install a revision of a Cyrus mod, or update the one already delivered (same project). */

