  const result = { assets: { status: "none", namespace: o.project.namespace, projectId: o.project.id, revisionId: o.revisionId ?? `rev_${o.id}`, textures: [], dropped: [], pack: null, loader: null, notices: [], datapacks: dps } };
  return {
    build: { id: o.id, userId: o.userId, status: "succeeded", pluginName: o.pluginName, jarName: o.jarName, jarPath: `/mem/${o.id}.jar`, jarSha256: sha(o.jar), mcVersion: o.mcVersion, result, rootBuildId: o.rootBuildId ?? null },
    datapackRows: rows,
  };
}

export class MemPortal {
  jobs: MemJob[] = [];
  serverMods = new Map<string, MemServerMod>();
  builds = new Map<string, DeliveryBuildRow & DeliveryBuild>();
  jars = new Map<string, Buffer>();
  datapackRows = new Map<string, { assetKey: string; provenance: unknown }[]>();
  projects = new Map<string, Project>();
  servers = new Map<string, { id: string; userId: string; name: string; eligible: boolean }>();
  audit: { userId: string; action: string; detail: string }[] = [];
  user: { id: string } | null = null;
  rate = true;
  installCheck: (a: { serverId: string; acked: string[] }) => HostCheck = ({ serverId }) => { const s = this.servers.get(serverId); return s?.eligible ? { ok: true, serverName: s.name } : { ok: false, status: 409, error: "That server can't take this plugin.", code: "not_eligible" }; };
  private seq = 0;
  private t = Date.parse("2026-10-10T12:00:00Z");
  private now = () => new Date((this.t += 1000));

  addBuild(b: ReturnType<typeof makeBuild>, jar: Buffer) {
    this.builds.set(b.build.id, b.build);
    this.jars.set(b.build.jarPath!, jar);
    const rev = (b.build.result as { assets: { revisionId: string } }).assets.revisionId;
    this.datapackRows.set(rev, b.datapackRows);
  }
  gm = (rootBuildId: string) => `gm_${rootBuildId}`;
  modRow = (serverId: string, root: string) => [...this.serverMods.values()].find((m) => m.serverId === serverId && m.modId === this.gm(root)) ?? null;

  apiDeps(env: Record<string, string | undefined>): DeliveryApiDeps {
    return {
      env,
      currentUser: async () => this.user,
      rateLimit: () => (this.rate ? { ok: true, retryAfterSec: 0 } : { ok: false, retryAfterSec: 30 }),
      build: async (uid, id) => { const b = this.builds.get(id); return b && b.userId === uid ? b : null; },
      project: async (uid, id) => { const p = this.projects.get(id); return p && p.userId === uid ? { id: p.id, rootBuildId: p.rootBuildId } : null; },
      checkInstall: async (a) => { const s = this.servers.get(a.serverId); if (!s || s.userId !== a.userId) return { ok: false, status: 404, error: "Server not found.", code: "not_found" }; return this.installCheck(a); },
      checkServer: async (a) => { const s = this.servers.get(a.serverId); return s && s.userId === a.userId ? { ok: true, serverName: s.name } : { ok: false, status: 404, error: "Server not found.", code: "not_found" }; },
      enqueue: async (a) => {
        const s = this.servers.get(a.serverId);
        if (!s || s.userId !== a.userId) return { ok: false, status: 404, error: "Server not found.", code: "not_found" };
        const same = [...this.jobs].reverse().find((j) => j.serverId === a.serverId && (j.payload as { cyrusDelivery?: { key?: string } }).cyrusDelivery?.key === a.payload.key);
        if (same && reuseExisting(a.keyKind, same.status)) return { ok: true, jobId: same.id, reused: true };
        if (this.jobs.some((j) => j.serverId === a.serverId && (j.status === "QUEUED" || j.status === "RUNNING"))) return { ok: false, status: 409, error: "Another operation is already running on this server. Try again when it finishes.", code: "busy" };
        const root = a.payload.op === "deliver" ? (a.build!.rootBuildId ?? a.build!.id) : a.projectRootBuildId ?? null;
        let serverModId: string | undefined;
        let prev: { status: string; versionId: string | null } | null = null;
        if (root) {
          const ex = this.modRow(a.serverId, root);
          if (a.payload.op === "deliver") {
            if (ex?.status === "DISABLED") return { ok: false, status: 409, error: "switched off", code: "disabled" };
            if (ex && !["INSTALLED", "FAILED", "REMOVED"].includes(ex.status)) return { ok: false, status: 409, error: "busy", code: "busy" };
            prev = ex ? { status: ex.status, versionId: ex.versionId } : null;
            const row = ex ?? { id: `sm_${++this.seq}`, serverId: a.serverId, modId: this.gm(root), status: "", versionId: null, error: null, targetVersionId: null };
            Object.assign(row, { status: ex?.status === "INSTALLED" ? "UPDATING" : "INSTALLING", error: null, targetVersionId: a.payload.buildId });
            this.serverMods.set(row.id, row);
            serverModId = row.id;
          } else if (ex) {
            prev = { status: ex.status, versionId: ex.versionId };
            ex.status = "REMOVING";
            serverModId = ex.id;
          }
        }
        const at = this.now();
        const job: MemJob = { id: `job_${++this.seq}`, serverId: a.serverId, status: "QUEUED", error: null, payload: { cyrusDelivery: { ...a.payload, ...(serverModId ? { serverModId, prev } : {}) } }, createdAt: at, updatedAt: at, attempts: 0 };
        this.jobs.push(job);
        this.audit.push({ userId: a.userId, action: "cyrus.delivery.requested", detail: `${a.serverId} job=${job.id} ${a.payload.op}` });
        return { ok: true, jobId: job.id, reused: false };
      },
      job: async (uid, id) => { const j = this.jobs.find((x) => x.id === id); return j && this.servers.get(j.serverId ?? "")?.userId === uid ? j : null; },
      jobs: async (uid, f) => this.jobs.filter((j) => this.servers.get(j.serverId ?? "")?.userId === uid && (!f.serverId || j.serverId === f.serverId)).reverse().slice(0, f.limit),
    };
  }

  jobDeps(env: Record<string, string | undefined>, host: (serverId: string) => DeliveryHost): DeliveryJobDeps<{ id: string; userId: string }> {
    return {
      env,
      server: async (id) => { const s = this.servers.get(id); return s ? { id: s.id, userId: s.userId } : null; },
      build: async (id) => this.builds.get(id) ?? null,
      readJar: async (p) => this.jars.get(p) ?? null,
      projectForRoot: async (root) => [...this.projects.values()].find((p) => p.rootBuildId === root) ?? null,
      project: async (id) => this.projects.get(id) ?? null,
      datapackAssets: async (rev) => this.datapackRows.get(rev) ?? [],
      host: (server) => host(server.id),
      storeResult: async (id, result) => { const j = this.jobs.find((x) => x.id === id)!; j.payload = { ...(j.payload as object), result: { cyrusDelivery: result } }; },
      audit: async (userId, action, detail) => { this.audit.push({ userId, action, detail }); },
      installRow: async (u: InstallRowUpdate) => {
        const row = this.serverMods.get(u.serverModId);
        if (!row) return;
        if (u.kind === "delivered") Object.assign(row, { status: "INSTALLED", versionId: u.buildId, error: null, targetVersionId: null });
        else if (u.kind === "removed") this.serverMods.delete(row.id);
        else if (u.kind === "restore") Object.assign(row, { status: u.prev.status, versionId: u.prev.versionId, error: u.error, targetVersionId: null });
        else Object.assign(row, { status: "FAILED", error: u.error, targetVersionId: null });
      },
      noRetry: async (id) => { const j = this.jobs.find((x) => x.id === id); if (j) j.attempts = 99; },
    };
  }

  /** The worker: claim the oldest queued job and run it (DONE / FAILED like the real claim loop). */
  async runNext(deps: DeliveryJobDeps<{ id: string; userId: string }>): Promise<MemJob | null> {
    const j = this.jobs.find((x) => x.status === "QUEUED");
    if (!j) return null;
    j.status = "RUNNING"; j.attempts++;
    try { await runDeliveryJob(j, deps); j.status = "DONE"; }
    catch (e) { j.status = "FAILED"; j.error = (e as Error).message.slice(0, 1000); }
    j.updatedAt = this.now();
    return j;
  }
}

export const post = (body: unknown, headers: Record<string, string> = {}) => new Request("http://x/api/cyrus/delivery/v1", { method: "POST", headers: { "content-type": "application/json", ...headers }, body: JSON.stringify(body) });

