// Wiring phase 2, item 1: the delivery ENQUEUE path. Pure rules (payload, keys, parts, acknowledgements, the status
// read model), the framework-free API (flags, ownership, checks, idempotency, busy), and the whole loop with the
// in-memory queue + the REAL job body + the orchestrator against the fake server: portal request -> job ->
// orchestrator -> server -> stored result -> status, including a world generation pack and a rollback.
import { describe, it, after } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { parseDeliveryPayload, readDeliveryPayload, deliveryKey, reuseExisting, deliveryParts, deliveryStatus, missingAcks } from "../lib/cyrus/delivery/request";
import { handleDeliveryList, handleDeliveryStatus, handleRequestDelivery } from "../lib/cyrus/delivery/api";
import { installRowUpdate, runDeliveryJob } from "../lib/cyrus/delivery/job";
import { FakeServer, pluginJar, seedServer } from "./_cyrus-delivery-fakehost";
import { MemPortal, makeBuild, post } from "./_cyrus-delivery-memqueue";
import type { DeliveryResult } from "../lib/cyrus/delivery/types";

const WG = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-worldgen/showcase.json"), "utf8"));
const NS = "nx_worldg01";
const ON = { CYRUS_DELIVERY: "1", CYRUS_MANAGED_PLUGINS_REAL: "1", CYRUS_DATAPACK_DELIVERY_REAL: "1", CYRUS_DATAPACK_STUDIO: "1", CYRUS_WORLDGEN: "1" };
const job = (o: Partial<{ status: string; error: string | null; payload: unknown }>) => ({ id: "j1", serverId: "s1", status: "QUEUED", error: null, payload: { cyrusDelivery: { v: 1, op: "deliver", buildId: "b1", restartPolicy: "now" } }, createdAt: new Date(0), updatedAt: new Date(0), ...o });

describe("delivery payload + keys (pure)", () => {
  it("parses the four ops and refuses incomplete ones", () => {
    assert.equal(parseDeliveryPayload({ v: 1, op: "deliver" }), null);
    assert.equal(parseDeliveryPayload({ v: 2, op: "deliver", buildId: "b" }), null);
    assert.equal(parseDeliveryPayload({ v: 1, op: "rm -rf", buildId: "b" }), null);
    assert.equal(parseDeliveryPayload({ v: 1, op: "uninstall" }), null);
    assert.equal(parseDeliveryPayload({ v: 1, op: "modpack_install", pack: { packId: "mp_abc", versionId: "1.0.0", sha256: "0".repeat(64) } }), null);
    assert.ok(parseDeliveryPayload({ v: 1, op: "modpack_install", pack: { packId: "mp_abcdefABCDEF", versionId: "1.0.0", sha256: "0".repeat(64) } }));
    assert.ok(parseDeliveryPayload({ v: 1, op: "modpack_uninstall", packId: "mp_abcdefABCDEF" }));
    const p = parseDeliveryPayload({ v: 1, op: "deliver", buildId: "b1", restartPolicy: "weird", acknowledge: ["restart", "restart", "bad id!"], prev: { status: "INSTALLED", versionId: "b0" }, buildIdX: 1 })!;
    assert.deepEqual(p, { v: 1, op: "deliver", buildId: "b1", restartPolicy: "now", acknowledge: ["restart"], prev: { status: "INSTALLED", versionId: "b0" } });
    assert.equal(readDeliveryPayload({ op: "install", modId: "m" }), null, "ordinary GAME_MOD_SYNC payloads are never deliveries");
    assert.equal(readDeliveryPayload(null), null);
  });
  it("client keys are scoped to the account; derived keys only reuse a live job", () => {
    const a = deliveryKey({ userId: "u1", serverId: "s", op: "deliver", subject: "b", restartPolicy: "now", clientKey: "abcdefgh12" });
    const b = deliveryKey({ userId: "u2", serverId: "s", op: "deliver", subject: "b", restartPolicy: "now", clientKey: "abcdefgh12" });
    assert.equal(a.kind, "client"); assert.notEqual(a.key, b.key);
    const d = deliveryKey({ userId: "u1", serverId: "s", op: "deliver", subject: "b", restartPolicy: "now" });
    assert.equal(d.kind, "derived"); assert.match(d.key, /^d_[0-9a-f]{40}$/);
    assert.notEqual(d.key, deliveryKey({ userId: "u1", serverId: "s", op: "deliver", subject: "b", restartPolicy: "next_restart" }).key);
    assert.equal(reuseExisting("derived", "QUEUED"), true); assert.equal(reuseExisting("derived", "DONE"), false); assert.equal(reuseExisting("derived", "FAILED"), false);
    assert.equal(reuseExisting("client", "FAILED"), true);
  });
});

describe("what would be delivered + acknowledgements (pure)", () => {
  const { build } = makeBuild({ id: "b1", userId: "u1", pluginName: "WgMod", jarName: "WgMod-1.0.0.jar", jar: pluginJar("WgMod"), mcVersion: "1.21.11", project: { id: "cp1", namespace: NS }, datapackSpec: WG, worldgen: true });
  it("every switch on: plugin + worldgen, restart + worldgen acks", () => {
    const v = deliveryParts(build.result, "WgMod", ON);
    assert.deepEqual(v.parts.map((p) => [p.kind, p.delivered]), [["plugin", true], ["worldgen", true]]);
    assert.deepEqual(v.acks.map((a) => a.id), ["restart", "worldgen"]);
    assert.equal(v.worldgen, true);
    assert.deepEqual(missingAcks(v.acks, ["restart"]).map((m) => m.id), ["worldgen"]);
  });
  it("worldgen off / data packs off: the part is listed as left out, with the reason", () => {
    const off = deliveryParts(build.result, "WgMod", { ...ON, CYRUS_WORLDGEN: "0" });
    assert.deepEqual(off.parts[1], { kind: "worldgen", name: "crystal_realm", delivered: false, reason: "world generation is switched off" });
    assert.deepEqual(off.acks.map((a) => a.id), ["restart"]);
    const dp = deliveryParts(build.result, "WgMod", { CYRUS_DELIVERY: "1" });
    assert.equal(dp.parts[1].reason, "data pack delivery is switched off");
    assert.equal(deliveryParts({}, null, ON).deliverable, false);
  });
});

describe("status read model (pure): never softer than what happened", () => {
  it("queued / running / failed-before-running / DONE without a result", () => {
    assert.equal(deliveryStatus(job({})).state, "queued");
    assert.equal(deliveryStatus(job({ status: "RUNNING" })).pending, true);
    const f = deliveryStatus(job({ status: "FAILED", error: "cyrus delivery: Cyrus delivery is switched off (CYRUS_DELIVERY is not 1); nothing was changed" }));
    assert.equal(f.state, "failed"); assert.equal(f.ok, false); assert.match(f.headline, /did not run/);
    const d = deliveryStatus(job({ status: "DONE" }));
    assert.equal(d.ok, false, "a DONE job without a stored result is never shown as a success");
  });
  it("rolled back and rollback incomplete are surfaced as such", () => {
    const rb = (outcome: string, ok: boolean) => deliveryStatus(job({ status: "FAILED", payload: { cyrusDelivery: { v: 1, op: "deliver", buildId: "b1" }, result: { cyrusDelivery: { ok: false, outcome, failedStep: "health", error: "plugin X is not enabled", rollback: { ok, restored: 2, removed: 1, mismatches: ok ? [] : ["a"], restarted: true, health: { ok } }, steps: [{ step: "health", status: "failed", detail: "x" }], notes: [] } } } }));
    const a = rb("rolled_back", true);
    assert.equal(a.state, "rolled_back"); assert.equal(a.needsAttention, false); assert.match(a.headline, /rolled back/); assert.equal(a.rollback!.cameBackHealthy, true);
    const b = rb("rollback_incomplete", false);
    assert.equal(b.needsAttention, true); assert.match(b.headline, /could not fully restore/); assert.equal(b.rollback!.mismatches, 1);
  });
  it("install row: delivered / restore previous on refusal + rollback / FAILED on incomplete rollback", () => {
    const p = parseDeliveryPayload({ v: 1, op: "deliver", buildId: "b2", serverModId: "sm1", prev: { status: "INSTALLED", versionId: "b1" } })!;
    const r = (outcome: DeliveryResult["outcome"], ok: boolean) => ({ ok, outcome, error: "e" }) as DeliveryResult;
    assert.deepEqual(installRowUpdate(p, r("updated", true), "x.jar"), { kind: "delivered", serverModId: "sm1", buildId: "b2", jarName: "x.jar" });
    assert.equal(installRowUpdate(p, r("rolled_back", false), null)!.kind, "restore");
    assert.equal(installRowUpdate(p, r("refused", false), null)!.kind, "restore");
    assert.equal(installRowUpdate(p, r("rollback_incomplete", false), null)!.kind, "failed");
  });
});

describe("delivery API (in-memory deps)", () => {
  const portal = () => {
    const m = new MemPortal();
    m.user = { id: "u1" };
    m.servers.set("s1", { id: "s1", userId: "u1", name: "My server", eligible: true });
    m.servers.set("s9", { id: "s9", userId: "u9", name: "Not mine", eligible: true });
    m.projects.set("cp1", { id: "cp1", namespace: NS, userId: "u1", rootBuildId: "b1" });
    const jar = pluginJar("WgMod");
    m.addBuild(makeBuild({ id: "b1", userId: "u1", pluginName: "WgMod", jarName: "WgMod-1.0.0.jar", jar, mcVersion: "1.21.11", project: { id: "cp1", namespace: NS }, datapackSpec: WG, worldgen: true }), jar);
    const other = pluginJar("Other");
    m.addBuild(makeBuild({ id: "b9", userId: "u9", pluginName: "Other", jarName: "Other.jar", jar: other, mcVersion: "1.21.11", project: { id: "cp9", namespace: "nx_other001" } }), other);
    return m;
  };
  const deliver = (extra: Record<string, unknown> = {}) => ({ op: "deliver", buildId: "b1", serverId: "s1", acked: ["restart", "worldgen"], ...extra });

  it("off, signed out, or someone else's build/server: 404 (invisible)", async () => {
    const m = portal();
    assert.equal((await handleRequestDelivery(post(deliver()), m.apiDeps({}))).status, 404);
    assert.equal((await handleDeliveryList(new URL("http://x/"), m.apiDeps({}))).status, 404);
    m.user = null;
    assert.equal((await handleRequestDelivery(post(deliver()), m.apiDeps(ON))).status, 404);
    m.user = { id: "u1" };
    assert.equal((await handleRequestDelivery(post(deliver({ buildId: "b9" })), m.apiDeps(ON))).status, 404);
    assert.equal((await handleRequestDelivery(post(deliver({ serverId: "s9" })), m.apiDeps(ON))).status, 404);
    assert.equal((await handleRequestDelivery(post({ op: "uninstall", projectId: "cp9", serverId: "s1" }), m.apiDeps(ON))).status, 404);
    assert.equal(m.jobs.length, 0);
  });
  it("bad input 400, rate limit 429, next_restart with worldgen 409, missing acks 409, host check refusal passes through", async () => {
    const m = portal();
    assert.equal((await handleRequestDelivery(post({ op: "deliver", buildId: "b1" }), m.apiDeps(ON))).status, 400);
    assert.equal((await handleRequestDelivery(post(deliver(), { "idempotency-key": "x" }), m.apiDeps(ON))).status, 400);
    const nr = await handleRequestDelivery(post(deliver({ restartPolicy: "next_restart" })), m.apiDeps(ON));
    assert.equal(nr.status, 409); assert.equal((await nr.json()).code, "needs_restart");
    const na = await handleRequestDelivery(post(deliver({ acked: ["restart"] })), m.apiDeps(ON));
    assert.equal(na.status, 409);
    const nb = await na.json();
    assert.equal(nb.code, "needs_ack"); assert.deepEqual(nb.acks.map((a: { id: string }) => a.id), ["worldgen"]);
    m.installCheck = () => ({ ok: false, status: 409, error: "Please confirm: version", code: "needs_plan_ack", plan: { warnings: [{ id: "version" }] } });
    const pc = await handleRequestDelivery(post(deliver()), m.apiDeps(ON));
    assert.equal(pc.status, 409); assert.equal((await pc.json()).code, "needs_plan_ack");
    m.rate = false;
    assert.equal((await handleRequestDelivery(post(deliver()), m.apiDeps(ON))).status, 429);
    assert.equal(m.jobs.length, 0);
  });
  it("preview enqueues nothing and lists parts + acks", async () => {
    const m = portal();
    const r = await handleRequestDelivery(post(deliver({ preview: true, acked: [] })), m.apiDeps({ ...ON, CYRUS_WORLDGEN: "0" }));
    assert.equal(r.status, 200);
    const b = await r.json();
    assert.equal(b.preview, true); assert.deepEqual(b.missingAcks, ["restart"]); assert.equal(b.parts[1].delivered, false);
    assert.equal(m.jobs.length, 0);
  });
  it("enqueue: 202 + one job + install row INSTALLING; same client key replays; derived key reuses while queued; busy 409", async () => {
    const m = portal();
    const r = await handleRequestDelivery(post(deliver(), { "idempotency-key": "click-0001" }), m.apiDeps(ON));
    assert.equal(r.status, 202);
    const b = await r.json();
    assert.equal(b.status.state, "queued"); assert.equal(m.jobs.length, 1);
    const p = readDeliveryPayload(m.jobs[0].payload)!;
    assert.equal(p.requestedBy, "u1"); assert.deepEqual(p.acknowledge, ["restart", "worldgen"]); assert.match(p.key!, /^c_/); assert.ok(p.serverModId); assert.equal(p.prev, null);
    assert.equal(m.serverMods.get(p.serverModId!)!.status, "INSTALLING");
    const again = await handleRequestDelivery(post(deliver(), { "idempotency-key": "click-0001" }), m.apiDeps(ON));
    assert.equal(again.status, 200); assert.equal((await again.json()).reused, true);
    const derived = await handleRequestDelivery(post(deliver()), m.apiDeps(ON));
    assert.equal(derived.status, 409, "a different (derived) key while a job runs on the server: busy"); assert.equal((await derived.json()).code, "busy");
    assert.equal(m.jobs.length, 1);
    assert.equal(m.audit.filter((a) => a.action === "cyrus.delivery.requested").length, 1);
  });
  it("status: only the owner sees a job", async () => {
    const m = portal();
    await handleRequestDelivery(post(deliver()), m.apiDeps(ON));
    assert.equal((await handleDeliveryStatus(m.jobs[0].id, m.apiDeps(ON))).status, 200);
    m.user = { id: "u9" };
    assert.equal((await handleDeliveryStatus(m.jobs[0].id, m.apiDeps(ON))).status, 404);
    assert.equal((await (await handleDeliveryList(new URL("http://x/?serverId=s1"), m.apiDeps(ON))).json()).deliveries.length, 0);
  });
});

describe("portal -> job -> orchestrator -> server -> status (in-memory worker, fake server)", () => {
  const servers: FakeServer[] = [];
  after(() => servers.forEach((s) => s.cleanup()));
  it("worldgen delivery, a rolled-back broken update, then uninstall; the install row follows each outcome", async () => {
    const srv = new FakeServer(); servers.push(srv); seedServer(srv);
    const m = new MemPortal();
    m.user = { id: "u1" };
    m.servers.set("s1", { id: "s1", userId: "u1", name: "My server", eligible: true });
    m.projects.set("cp1", { id: "cp1", namespace: NS, userId: "u1", rootBuildId: "b1" });
    const jar1 = pluginJar("WgMod"), jar2 = pluginJar("WgModBroken");
