});

describe("portal -> job -> orchestrator -> server -> status (in-memory worker, fake server)", () => {
  const servers: FakeServer[] = [];
  after(() => servers.forEach((s) => s.cleanup()));
  it("worldgen delivery, a rolled-back broken update, then uninstall; the install row follows each outcome", async () => {
    const srv = new FakeServer(); servers.push(srv); seedServer(srv);
    const m = new MemPortal();
    m.user = { id: "u1" };
    m.servers.set("s1", { id: "s1", userId: "u1", name: "My server", eligible: true });
    m.projects.set("cp1", { id: "cp1", namespace: NS, userId: "u1", rootBuildId: "b1" });
    const jar1 = pluginJar("WgMod"), jar2 = pluginJar("WgModBroken");
    m.addBuild(makeBuild({ id: "b1", userId: "u1", pluginName: "WgMod", jarName: "WgMod-1.0.0.jar", jar: jar1, mcVersion: "1.21.11", project: { id: "cp1", namespace: NS }, datapackSpec: WG, worldgen: true, revisionId: "rev1" }), jar1);
    m.addBuild(makeBuild({ id: "b2", userId: "u1", rootBuildId: "b1", pluginName: "WgModBroken", jarName: "WgMod-1.0.1.jar", jar: jar2, mcVersion: "1.21.11", project: { id: "cp1", namespace: NS }, datapackSpec: WG, worldgen: true, revisionId: "rev2" }), jar2);
    const api = m.apiDeps(ON);
    const jd = m.jobDeps(ON, () => srv.host());
    const status = async (id: string) => (await (await handleDeliveryStatus(id, api)).json()).status;

    // 1. worldgen delivery
    const r1 = await (await handleRequestDelivery(post({ op: "deliver", buildId: "b1", serverId: "s1", acked: ["restart", "worldgen"] }), api)).json();
    await m.runNext(jd);
    const s1 = await status(r1.jobId);
    assert.equal(s1.state, "delivered", JSON.stringify(s1)); assert.equal(s1.ok, true); assert.equal(s1.apply.restarted, true); assert.equal(s1.health.ok, true);
    assert.ok(srv.files("opt/mc/world/datapacks").some((f) => f.includes("crystal_realm")), "the worldgen pack is on the server");
    assert.ok(srv.files("opt/mc/plugins").includes("WgMod-1.0.0.jar"));
    const row = m.modRow("s1", "b1")!;
    assert.equal(row.status, "INSTALLED"); assert.equal(row.versionId, "b1");
    const treeAfter1 = srv.tree({ excludeJournal: true });

    // 2. update to a build whose plugin fails to enable: health fails -> rolled back -> previous state, row restored
    const r2 = await (await handleRequestDelivery(post({ op: "deliver", buildId: "b2", serverId: "s1", acked: ["restart", "worldgen"] }), api)).json();
    assert.equal(m.modRow("s1", "b1")!.status, "UPDATING");
    await m.runNext(jd);
    const s2 = await status(r2.jobId);
    assert.equal(s2.state, "rolled_back", JSON.stringify(s2)); assert.equal(s2.ok, false); assert.equal(s2.failedStep, "health");
    assert.equal(s2.rollback.ok, true); assert.equal(s2.rollback.restarted, true); assert.equal(s2.rollback.cameBackHealthy, true);
    assert.equal(srv.tree({ excludeJournal: true }), treeAfter1, "exactly the previous files");
    assert.equal(m.jobs.find((j) => j.id === r2.jobId)!.status, "FAILED");
    const row2 = m.modRow("s1", "b1")!;
    assert.equal(row2.status, "INSTALLED"); assert.equal(row2.versionId, "b1"); assert.match(row2.error!, /^Rolled back: /);

    // 3. uninstall: row removed, dimension folders kept and listed
    const r3 = await (await handleRequestDelivery(post({ op: "uninstall", projectId: "cp1", serverId: "s1", acked: ["restart"] }), api)).json();
    assert.equal(m.modRow("s1", "b1")!.status, "REMOVING");
    await m.runNext(jd);
    const s3 = await status(r3.jobId);
    assert.equal(s3.state, "uninstalled", JSON.stringify(s3));
    assert.equal(m.modRow("s1", "b1"), null);
    assert.ok(!srv.files("opt/mc/plugins").includes("WgMod-1.0.0.jar"));
    const list = await (await handleDeliveryList(new URL("http://x/?serverId=s1"), api)).json();
    assert.deepEqual(list.deliveries.map((d: { state: string }) => d.state), ["uninstalled", "rolled_back", "delivered"]);
    assert.ok(m.audit.some((a) => a.action === "cyrus.delivery.failed") && m.audit.some((a) => a.action === "cyrus.delivery.ok"));
  });

  it("the worker refuses when its own switch is off, the build is someone else's, or the requester is not the owner (row restored)", async () => {
    const srv = new FakeServer(); servers.push(srv); seedServer(srv);
    const m = new MemPortal();
    m.user = { id: "u1" };
    m.servers.set("s1", { id: "s1", userId: "u1", name: "My server", eligible: true });
    m.projects.set("cp1", { id: "cp1", namespace: NS, userId: "u1", rootBuildId: "b1" });
    const jar = pluginJar("WgMod");
    m.addBuild(makeBuild({ id: "b1", userId: "u1", pluginName: "WgMod", jarName: "WgMod-1.0.0.jar", jar, mcVersion: "1.21.11", project: { id: "cp1", namespace: NS } }), jar);
    const before = srv.tree();
    await handleRequestDelivery(post({ op: "deliver", buildId: "b1", serverId: "s1", acked: ["restart"] }), m.apiDeps(ON));
    const j = await m.runNext(m.jobDeps({ ...ON, CYRUS_DELIVERY: "0" }, () => srv.host()));
    assert.equal(j!.status, "FAILED"); assert.match(j!.error!, /switched off/); assert.equal(j!.attempts, 99);
    assert.equal(deliveryStatus(j!).state, "failed");
    assert.equal(m.modRow("s1", "b1")!.status, "FAILED", "a first install that never ran: FAILED with the reason");
    assert.equal(srv.tree(), before, "nothing touched");
    // a forged payload naming another account's build
    const forged = { id: "jf", serverId: "s1", payload: { cyrusDelivery: { v: 1, op: "deliver", buildId: "b1", requestedBy: "u9", restartPolicy: "now" } } };
    await assert.rejects(runDeliveryJob(forged, m.jobDeps(ON, () => srv.host())), /not come from the server's owner/);
    m.builds.get("b1")!.userId = "u9";
    await assert.rejects(runDeliveryJob({ ...forged, payload: { cyrusDelivery: { v: 1, op: "deliver", buildId: "b1", restartPolicy: "now" } } }, m.jobDeps(ON, () => srv.host())), /another account/);
    assert.equal(srv.tree(), before);
  });
});

