// REAL run on node-2 (wiring phase 2, item 1; not part of the unit suite): the WHOLE enqueue path against real Paper
// boots. The portal function (lib/cyrus/delivery/api.ts handleRequestDelivery, with in-memory host deps) creates the
// job, the in-memory queue hands it to the REAL host-neutral job body (lib/cyrus/delivery/job.ts), which assembles the
// release from the stored build (releaseFromBuild: jar sha, data pack REBUILT from its stored spec), and the
// orchestrator delivers it to a disposable server dir under /tank/nxeon-build/tmp/cyrus-r29/ whose every restart is a
// real Test Flight boot (one flight at a time, busy retried). The status read model (handleDeliveryStatus) is read back.
//   scripts/devhost run --lock -- npx tsx test/cyrus-delivery-enqueue-real.ts --local [--version 1.21.11] [--out f.json]
// Scenarios:
//   1  deliver build b1 = TfItemModel jar (real plugin) + the worldgen showcase pack (two dimensions) -> delivered
//   2  deliver build b2 (same mod) whose jar cannot load (missing main class) + the same pack -> the health check fails
//      -> rolled back to b1's exact files -> restarted -> came up healthy; the install row is back on b1
//   3  uninstall -> removed, dimension folders kept and listed
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, type Remote, type RunResult } from "../lib/cyrus/testflight/client";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";
import { LocalGuestFs } from "../lib/mods/guest-fs";
import { inspectJar } from "../lib/cyrus/inventory/jar";
import { zip } from "../lib/cyrus/textures/zip";
import { handleDeliveryStatus, handleRequestDelivery } from "../lib/cyrus/delivery/api";
import type { DeliveryHost, HealthReport, ServerSession, TxnFs } from "../lib/cyrus/delivery/types";
import { MemPortal, makeBuild, post } from "./_cyrus-delivery-memqueue";

const TF_ROOT = "/tank/nxeon-build/tmp/testflight";
const WORK = "/tank/nxeon-build/tmp/cyrus-r29";
const FX = `${TF_ROOT}/inbox/fx`;
const NS = "nx_worldg01"; // the worldgen showcase namespace
const BASE = "/opt/mc";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const h = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const arg = (k: string, d: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : d; };
const VERSION = arg("--version", "1.21.11");
const ENV = { CYRUS_DELIVERY: "1", CYRUS_MANAGED_PLUGINS_REAL: "1", CYRUS_DATAPACK_DELIVERY_REAL: "1", CYRUS_DATAPACK_STUDIO: "1", CYRUS_WORLDGEN: "1" };
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
const REMOTE = process.argv.includes("--local") ? localRemote : undefined;

async function fly(spec: TestFlightSpec, label: string): Promise<RunResult> {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: REMOTE });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy, retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

function treeHash(dir: string, skip = "root/.nxeon-cyrus/delivery-journal"): string {
  const out: string[] = [];
  const walk = (d: string) => { for (const n of readdirSync(d).sort()) { const p = path.join(d, n), rel = path.relative(dir, p); if (rel.startsWith(skip)) continue; if (statSync(p).isDirectory()) { out.push(`D ${rel}`); walk(p); } else out.push(`F ${rel} ${h(readFileSync(p))}`); } };
  walk(dir);
  return h(Buffer.from(out.join("\n")));
}

/** A server that is a directory; every restart boots its CURRENT plugins + world data packs on real Paper (Test Flight). */
function flightHost(root: string, flights: unknown[]): DeliveryHost {
  const fs = new LocalGuestFs(root);
  let last: RunResult | null = null;
  let lastDatapacks: string[] = [];
  const local = (p: string) => path.join(root, p);
  const session: ServerSession = {
    fs, base: BASE, levelName: "world", mcVersion: VERSION,
    async restart() {
      const plugins = readdirSync(local(`${BASE}/plugins`)).filter((n) => n.endsWith(".jar")).sort().map((n) => ({ localPath: local(`${BASE}/plugins/${n}`) }));
      const dpDir = local(`${BASE}/world/datapacks`);
      const datapacks = (() => { try { return readdirSync(dpDir).filter((n) => n.endsWith(".zip")).sort().map((n) => ({ name: n.replace(/\.zip$/, "").toLowerCase().replace(/[^a-z0-9_.-]/g, "-").slice(0, 64), localPath: path.join(dpDir, n) })); } catch { return []; } })();
      const names = plugins.map((p) => inspectJar(path.basename(p.localPath), `plugins/${path.basename(p.localPath)}`, readFileSync(p.localPath), { bytecode: false }).descriptor?.name).filter((n): n is string => !!n);
      const spec: TestFlightSpec = { version: VERSION, plugins, datapacks, rcon: [{ id: "answers", command: "list", required: false }], timeouts: { bootSec: 200, totalSec: 480 } };
      lastDatapacks = datapacks.map((d) => d.name);
      try {
        const t0 = Date.now();
        last = await fly(spec, "restart");
        flights.push({ at: new Date().toISOString(), plugins: names, datapacks: lastDatapacks, overall: last.summary.overall, checks: last.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence.slice(0, 6) })), bootMs: last.report.bootMs, peakRssKb: last.report.peakRssKb, wallMs: Date.now() - t0, runId: last.report.runId, paper: last.report.engine?.paper ?? null, jdk: last.report.engine?.jdk?.version ?? null });
        console.log(`  flight: ${last.summary.overall} (${last.report.checks.map((c) => `${c.id}=${c.status}`).join(" ")})`);
        return { ok: true };
      } catch (e) { last = null; return { ok: false, error: (e as Error).message }; }
    },
    async health(): Promise<HealthReport> {
      const r = last?.report;
      if (!r) return { real: true, cameUp: false, answered: false, pluginsEnabled: [], errorLines: [], datapacksLoaded: [], evidence: ["no flight"] };
      const c = (id: string) => r.checks.find((x) => x.id === id);
      const boot = c("boot_done"), pe = c("plugins_enabled"), log = c("startup_log_clean"), rc = c("rcon_checks");
      const enabled = (pe?.evidence ?? []).map((l) => /^(\S+): enabled/.exec(l)?.[1]).filter((n): n is string => !!n);
      const dl = (rc?.evidence ?? []).find((l) => l.startsWith("datapacks-enabled ")) ?? "";
      return {
        real: true, cameUp: boot?.status === "pass", answered: (rc?.evidence ?? []).some((l) => l.startsWith("answers ") && /: ok/.test(l)) || c("clean_stop")?.status === "pass",
        pluginsEnabled: enabled, errorLines: log?.status === "fail" ? log.evidence.filter((l) => /ERROR|Exception|Caused by|Failed|Could not/.test(l)).slice(0, 10) : [],
        datapacksLoaded: /: ok/.test(dl) ? lastDatapacks.map((n) => `file/${n}.zip`) : [...dl.matchAll(/file\/([A-Za-z0-9_.-]+?)(?:\.zip)?(?=[\s,\]|"]|$)/g)].map((m) => `file/${m[1]}.zip`),
        evidence: [...(boot?.evidence ?? []).slice(0, 2), dl.slice(0, 200)],
      };
    },
  };
  const writeJar = async (f: TxnFs, target: string, data: Buffer) => { await f.writeFile(`${target}.nxeon-part`, data); await f.rename(`${target}.nxeon-part`, target); };
  return {
    env: ENV,
    async open() { return session; },
    managed: {
      async ensure({ key }) { return { ok: false, error: `${key} is not used in this run` }; },
      async release() { return { ok: true, action: "not_held" }; },
      async snapshot() { return "[]"; },
      async restore() { return { ok: true }; },
    },
    jar: {
      async install({ fs: f, base, release, previous }) {
        const target = `${base}/plugins/${release.plugin!.jarName}`;
        if (previous?.jar && previous.jar.target !== target && (await f.stat(previous.jar.target))) await f.remove(previous.jar.target);
        await writeJar(f, target, release.plugin!.bytes);
        return { ok: true, target };
      },
      async remove({ fs: f, record }) { if (record.jar && (await f.stat(record.jar.target))) await f.remove(record.jar.target); return { ok: true }; },
    },
  };
}

function seed(root: string) {
  const w = (rel: string, data: string | Buffer) => { const p = path.join(root, rel); mkdirSync(path.dirname(p), { recursive: true }); writeFileSync(p, data); };
  w(`${BASE.slice(1)}/server.properties`, "level-name=world\n");
  w(`${BASE.slice(1)}/version_history.json`, JSON.stringify({ currentVersion: `${VERSION} (MC: ${VERSION})` }));
  mkdirSync(path.join(root, BASE.slice(1), "plugins"), { recursive: true });
  mkdirSync(path.join(root, BASE.slice(1), "world/datapacks"), { recursive: true });
}

async function main() {
  const out: Record<string, unknown> = { what: "Cyrus wiring phase 2: portal request -> job -> orchestrator -> real Paper (Test Flight, node-2) -> status", date: new Date().toISOString(), version: VERSION, scenarios: {} as Record<string, unknown> };
  const save = () => { const f = arg("--out", ""); if (f) writeFileSync(f, JSON.stringify(out, null, 1)); };
  const root = path.join(WORK, `srv-${Date.now().toString(36)}`);
  mkdirSync(root, { recursive: true });
  seed(root);
  const flights: unknown[] = [];
  const host = flightHost(root, flights);
  const jar1 = readFileSync(`${FX}/TfItemModel-1.0.0.jar`);
  const pluginName = inspectJar("TfItemModel-1.0.0.jar", "plugins/TfItemModel-1.0.0.jar", jar1, { bytecode: false }).descriptor?.name ?? "TfItemModel";
  // the same plugin, but its main class does not exist: Paper cannot enable it
  const jar2 = zip([{ path: "plugin.yml", data: Buffer.from(`name: ${pluginName}\nversion: 1.0.1\nmain: dev.cyrus.r29.MissingMain\napi-version: "1.21"\n`) }]);
  const wg = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-worldgen/showcase.json"), "utf8"));
  const m = new MemPortal();
  m.user = { id: "u_owner" };
  m.servers.set("srv_r29", { id: "srv_r29", userId: "u_owner", name: "r29 flight server", eligible: true });
  m.projects.set("cp_r29flight1", { id: "cp_r29flight1", namespace: NS, userId: "u_owner", rootBuildId: "b_r29_1" });
  m.addBuild(makeBuild({ id: "b_r29_1", userId: "u_owner", pluginName, jarName: "TfItemModel-1.0.0.jar", jar: jar1, mcVersion: VERSION, project: { id: "cp_r29flight1", namespace: NS }, datapackSpec: wg, worldgen: true, revisionId: "rev_r29_1" }), jar1);
  m.addBuild(makeBuild({ id: "b_r29_2", userId: "u_owner", rootBuildId: "b_r29_1", pluginName, jarName: "TfItemModel-1.0.1.jar", jar: jar2, mcVersion: VERSION, project: { id: "cp_r29flight1", namespace: NS }, datapackSpec: wg, worldgen: true, revisionId: "rev_r29_2" }), jar2);
  const api = m.apiDeps(ENV);
  const jd = m.jobDeps(ENV, () => host);
  const S = out.scenarios as Record<string, unknown>;
  const request = async (body: unknown, key: string) => { const r = await handleRequestDelivery(post(body, { "idempotency-key": key }), api); return { http: r.status, body: await r.json() }; };
  const status = async (id: string) => (await (await handleDeliveryStatus(id, api)).json()).status;
  const files = () => readdirSync(path.join(root, "opt/mc/plugins")).sort().concat(readdirSync(path.join(root, "opt/mc/world/datapacks")).sort());
  try {
    console.log(`1: deliver b1 (TfItemModel + worldgen showcase) on ${VERSION}`);
    const t0 = treeHash(root);
    const q1 = await request({ op: "deliver", buildId: "b_r29_1", serverId: "srv_r29", acked: ["restart", "worldgen"] }, "r29-flight-0001");
    const replay = await request({ op: "deliver", buildId: "b_r29_1", serverId: "srv_r29", acked: ["restart", "worldgen"] }, "r29-flight-0001");
    await m.runNext(jd);
    const s1 = await status(q1.body.jobId);
    const t1 = treeHash(root);
    S["1"] = { request: { http: q1.http, jobId: q1.body.jobId, parts: q1.body.parts }, replay: { http: replay.http, reused: replay.body.reused, sameJob: replay.body.jobId === q1.body.jobId }, status: s1, jobStatus: m.jobs[0].status, row: m.modRow("srv_r29", "b_r29_1"), treeBefore: t0, treeAfter: t1, files: files() };
    console.log(`1: ${s1.state} - ${s1.headline}`); save();
    if (s1.state !== "delivered") throw new Error("scenario 1 did not deliver; stopping");

    console.log("2: deliver b2 (jar cannot load) -> expect rollback");
    const q2 = await request({ op: "deliver", buildId: "b_r29_2", serverId: "srv_r29", acked: ["restart", "worldgen"] }, "r29-flight-0002");
    const rowDuring = { ...m.modRow("srv_r29", "b_r29_1")! };
    await m.runNext(jd);
    const s2 = await status(q2.body.jobId);
    const t2 = treeHash(root);
    S["2"] = { request: { http: q2.http, jobId: q2.body.jobId }, rowWhileQueued: rowDuring, status: s2, jobStatus: m.jobs[1].status, jobError: m.jobs[1].error, row: m.modRow("srv_r29", "b_r29_1"), exactRestore: t1 === t2, files: files() };
    console.log(`2: ${s2.state} - ${s2.headline}; exact restore ${t1 === t2}`); save();

    console.log("3: uninstall");
    const q3 = await request({ op: "uninstall", projectId: "cp_r29flight1", serverId: "srv_r29", acked: ["restart"] }, "r29-flight-0003");
    await m.runNext(jd);
    const s3 = await status(q3.body.jobId);
