// Cyrus Mod Packs (wiring phase 2): one finished Cyrus build -> the Mod Pack members it contributes (PURE). The
// plugin jar (verified against its recorded sha256) and every data pack the build shipped, rebuilt deterministically
// from its stored spec to the recorded sha256 (the same rule as delivery, lib/cyrus/delivery/release.ts). Member ids
// are derived from the mod's ROOT build so a later version of the same mod is an "updated" member in the changelog.
// Resource packs are not carried into a pack yet (they are hosted, not stored as bytes): that is reported as a note.
import { createHash } from "node:crypto";
import { rebuildForDelivery } from "../datapack/deliver";
import type { MemberInput } from "./builder";

export type MemberBuild = { id: string; rootBuildId: string | null; pluginName: string | null; jarName: string | null; jarSha256: string | null; mcVersion: string; result: unknown };
export type MemberProject = { id: string; namespace: string };

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
export const memberIdFor = (rootBuildId: string, suffix = "") => `cy-${rootBuildId.toLowerCase().replace(/[^a-z0-9]/g, "").slice(-16)}${suffix ? `-${suffix}` : ""}`.slice(0, 64);

export function membersFromBuild(b: MemberBuild, jar: Buffer | null, project: MemberProject | null, datapackRows: { assetKey: string; provenance: unknown }[]): { ok: true; members: MemberInput[]; notes: string[] } | { ok: false; error: string } {
  if (!jar || !b.jarName || !b.pluginName) return { ok: false, error: `${b.id}: the build has no stored plugin jar` };
  if (b.jarSha256 && sha256(jar) !== b.jarSha256) return { ok: false, error: `${b.id}: the stored plugin jar does not match its checksum` };
  if (!project) return { ok: false, error: `${b.id}: the build has no Cyrus project, so it cannot join a Mod Pack` };
  const root = b.rootBuildId ?? b.id;
  const assets = (b.result as { assets?: { revisionId?: string | null; datapacks?: { name: string; sha256: string }[]; status?: string; loader?: unknown } } | null)?.assets ?? null;
  const revisionId = (assets?.revisionId ?? `build:${b.id}`).slice(0, 64);
  const proj = { projectId: project.id, revisionId, namespace: project.namespace };
  const notes: string[] = [];
  const version = `build-${b.id.slice(-10)}`;
  const members: MemberInput[] = [{ id: memberIdFor(root), kind: "plugin", origin: "cyrus", label: b.pluginName, version, project: proj, artifact: { name: b.jarName, bytes: jar } }];
  for (const row of assets?.datapacks ?? []) {
    const asset = datapackRows.find((x) => x.assetKey === row.name || (x.provenance as { packSha256?: string } | null)?.packSha256 === row.sha256);
    if (!asset) { notes.push(`${b.pluginName}: data pack ${row.name} has no stored spec, so it is not in the pack`); continue; }
    const rb = rebuildForDelivery((asset.provenance ?? {}) as Record<string, unknown>, project.namespace);
    if (!rb.ok || rb.sha256 !== row.sha256) { notes.push(`${b.pluginName}: data pack ${row.name} could not be rebuilt exactly, so it is not in the pack`); continue; }
    members.push({ id: memberIdFor(root, `dp-${rb.name.replace(/[^a-z0-9_-]/g, "").slice(0, 24)}`), kind: "datapack", origin: "cyrus", label: `${b.pluginName}: ${rb.name}`.slice(0, 120), version, project: proj, artifact: { name: `nxeon-${project.namespace}-${rb.name}.zip`, bytes: rb.zip } });
  }
  if (assets?.status === "ready" && assets.loader) notes.push(`${b.pluginName}: its resource pack is not carried into Mod Packs yet (install the mod on its own for its textures and sounds)`);
  return { ok: true, members, notes };
}

