// Wiring phase 2, item 2: Mod Pack routes (framework-free API, in-memory deps) over lib/cyrus/modpack, the worker
// payload expressing a pack op, and the install acknowledgement rule (EVERY open warning + the restart). The whole
// loop runs: create -> conflicts preview against the fake server -> install (refused until acknowledged) -> job ->
// the REAL job body -> deliverModPack -> files on the server -> status -> uninstall.
import "./_cyrus-server-only-shim";
import { describe, it, after } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { handleConflicts, handleCreate, handleGet, handleInstall, handleList, handleUninstall, handleValidate, type ModPackApiDeps } from "../lib/cyrus/modpack/api";
import { MemoryModPackStore, openPackArchive } from "../lib/cyrus/modpack/store";
import { membersFromBuild, memberIdFor } from "../lib/cyrus/modpack/members";
import { readDeliveryPayload } from "../lib/cyrus/delivery/request";
import { handleDeliveryStatus } from "../lib/cyrus/delivery/api";
import { runDeliveryJob } from "../lib/cyrus/delivery/job";
import { fsPlacer } from "../lib/cyrus/modpack/install";
import { scanServer } from "../lib/cyrus/inventory/scan";
import type { TxnFs } from "../lib/cyrus/delivery/types";
import { FakeServer, pluginJar, seedServer } from "./_cyrus-delivery-fakehost";
import { MemPortal, makeBuild } from "./_cyrus-delivery-memqueue";

const DP = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-datapack/showcase.json"), "utf8"));
const ENV = { CYRUS_MODPACKS: "1", CYRUS_DELIVERY: "1", CYRUS_MODPACK_INSTALL_REAL: "1", CYRUS_MANAGED_PLUGINS_REAL: "1" };
const req = (body: unknown, headers: Record<string, string> = {}) => new Request("http://x/api/cyrus/modpacks/v1", { method: "POST", headers: { "content-type": "application/json", ...headers }, body: JSON.stringify(body) });
const PERM = "\npermissions:\n  shared.perm:\n    default: op\n";

function world() {
  const srv = new FakeServer();
  seedServer(srv);
  const m = new MemPortal();
  m.user = { id: "u1" };
  m.servers.set("s1", { id: "s1", userId: "u1", name: "My server", eligible: true });
  m.servers.set("s9", { id: "s9", userId: "u9", name: "Not mine", eligible: true });
  const mk = (id: string, name: string, ns: string, extra = "", dp = false, userId = "u1") => {
    const jar = pluginJar(name, extra);
    m.projects.set(`cp_${id}`, { id: `cp_${id}`, namespace: ns, userId, rootBuildId: id });
    m.addBuild(makeBuild({ id, userId, pluginName: name, jarName: `${name}-1.0.0.jar`, jar, mcVersion: "1.21.11", project: { id: `cp_${id}`, namespace: ns }, ...(dp ? { datapackSpec: DP } : {}) }), jar);
  };
  mk("bA", "PackAlpha", "nx_dpstud10", PERM, true);
  mk("bB", "PackBeta", "nx_packbeta");
  mk("bC", "PackGamma", "nx_packgamm", PERM);
  mk("bX", "Foreign", "nx_foreign1", "", false, "u9");
  const store = new MemoryModPackStore();
  let n = 0;
  const deps: ModPackApiDeps = {
    env: ENV,
    currentUser: async () => m.user,
    rateLimit: () => ({ ok: true, retryAfterSec: 0 }),
    async members(uid, buildId) {
      const b = m.builds.get(buildId);
      if (!b || b.userId !== uid) return { ok: false, status: 404, error: `Mod ${buildId} was not found or is not finished.` };
      const proj = [...m.projects.values()].find((p) => p.rootBuildId === (b.rootBuildId ?? b.id)) ?? null;
      const rev = (b.result as { assets: { revisionId: string } }).assets.revisionId;
      const r = membersFromBuild(b, m.jars.get(b.jarPath!) ?? null, proj, m.datapackRows.get(rev) ?? []);
      return r.ok ? { ok: true, mcVersion: b.mcVersion, members: r.members, notes: r.notes } : { ok: false, status: 409, error: r.error };
    },
    store,
    async inventory(uid, sid) { if (m.servers.get(sid)?.userId !== uid) return null; return { inventory: await scanServer(srv.raw, { base: "/opt/mc" }), ownedPaths: [] }; },
    checkServer: m.apiDeps(ENV).checkServer,
    enqueue: m.apiDeps(ENV).enqueue,
    job: m.apiDeps(ENV).job,
    now: () => new Date("2026-10-10T12:00:00Z"),
    newId: () => `mp_test${String(++n).padStart(8, "0")}`,
  };
  const host = () => ({ ...srv.host(), modpackPlacer: (fs: TxnFs) => fsPlacer(fs) });
  const jobDeps = { ...m.jobDeps(ENV, host), async modpack(uid: string, ref: { packId: string; versionId: string; sha256: string }) { const z = await store.readVersion(uid, ref.packId, ref.versionId); return z ? openPackArchive(z, ref) : { ok: false as const, error: "the Mod Pack version was not found" }; } };
  return { srv, m, store, deps, jobDeps };
}

describe("Mod Pack members (pure)", () => {
  it("a build gives its jar + its data packs (rebuilt exactly), stable ids from the root build", () => {
    const { m, srv } = world(); srv.cleanup();
    const b = m.builds.get("bA")!;
    const r = membersFromBuild(b, m.jars.get(b.jarPath!)!, { id: "cp_bA", namespace: "nx_dpstud10" }, m.datapackRows.get("rev_bA")!);
    assert.ok(r.ok);
    assert.deepEqual(r.members.map((x) => [x.id, x.kind]), [[memberIdFor("bA"), "plugin"], [memberIdFor("bA", "dp-showcase"), "datapack"]].map(([id, k]) => [id.replace("dp-showcase", `dp-${r.members[1].artifact!.name.split("-").pop()!.replace(".zip", "")}`), k]));
    assert.ok(!membersFromBuild(b, pluginJar("Tampered"), { id: "cp_bA", namespace: "nx_dpstud10" }, []).ok, "a jar that does not match its checksum is refused");
    assert.ok(!membersFromBuild(b, m.jars.get(b.jarPath!)!, null, []).ok);
  });
});

describe("Mod Pack API", () => {
  const worlds: FakeServer[] = [];
  after(() => worlds.forEach((s) => s.cleanup()));

  it("off = 404 everywhere; install also needs CYRUS_DELIVERY", async () => {
    const w = world(); worlds.push(w.srv);
    const off = { ...w.deps, env: {} };
    for (const r of [await handleList(off), await handleValidate(req({}), off), await handleCreate(req({}), off), await handleGet("mp_x", off), await handleInstall("mp_x", req({}), off)]) assert.equal(r.status, 404);
    assert.equal((await handleInstall("mp_test00000001", req({ serverId: "s1" }), { ...w.deps, env: { CYRUS_MODPACKS: "1" } })).status, 404);
  });

  it("validate stores nothing; create stores 1.0.0; someone else's build is not found; bad body 400", async () => {
    const w = world(); worlds.push(w.srv);
    const v = await handleValidate(req({ name: "My pack", mcVersion: "1.21.11", members: [{ buildId: "bA" }, { buildId: "bB" }] }), w.deps);
    assert.equal(v.status, 200);
    const vb = await v.json();
    assert.equal(vb.ok, true); assert.equal(vb.members.length, 3);
    assert.equal((await w.store.list("u1")).length, 0);
    assert.equal((await handleCreate(req({ name: "x", mcVersion: "1.21.11", members: [{ buildId: "bX" }] }), w.deps)).status, 404);
    assert.equal((await handleCreate(req({ name: "", mcVersion: "1.21.11", members: [{ buildId: "bA" }] }), w.deps)).status, 400);
    assert.equal((await handleCreate(req({ name: "x", mcVersion: "9.9", members: [{ buildId: "bA" }] }), w.deps)).status, 400);
    assert.equal((await handleCreate(req({ name: "x", mcVersion: "1.21.11", members: [{ buildId: "bA" }, { buildId: "bA" }] }), w.deps)).status, 400);
    const c = await handleCreate(req({ name: "My pack", mcVersion: "1.21.11", members: [{ buildId: "bA" }, { buildId: "bB" }] }), w.deps);
    assert.equal(c.status, 201);
    const cb = await c.json();
    assert.equal(cb.pack.packId, "mp_test00000001"); assert.equal(cb.pack.latest, "1.0.0");
    const zip = await w.store.readVersion("u1", cb.pack.packId, "1.0.0");
    assert.ok(zip && openPackArchive(zip, { sha256: cb.pack.versions[0].sha256, packId: cb.pack.packId, versionId: "1.0.0" }).ok);
    assert.ok(!openPackArchive(zip!, { sha256: "0".repeat(64), packId: cb.pack.packId, versionId: "1.0.0" }).ok, "a tampered or swapped archive is refused");
    assert.equal((await (await handleList(w.deps)).json()).packs.length, 1);
    m_userSwap(w, "u9");
    assert.equal((await handleGet(cb.pack.packId, w.deps)).status, 404, "another account cannot see the pack");
  });

  it("open warnings (pack + server) must ALL be acknowledged, then install -> job -> server -> status; uninstall", async () => {
    const w = world(); worlds.push(w.srv);
    // the server already runs a plugin defining the same permission as PackAlpha: a warning against the server
    const fs = await import("node:fs");
    fs.writeFileSync(path.join(w.srv.dir, "opt/mc/plugins/Perms.jar"), pluginJar("PermOwner", PERM));
    // PackAlpha + PackGamma define the same permission: a warning inside the pack
    const c = await (await handleCreate(req({ name: "Perm pack", mcVersion: "1.21.11", members: [{ buildId: "bA" }, { buildId: "bC" }] }), w.deps)).json();
    const packId = c.pack.packId as string;
    assert.ok(c.pack.versions[0].openWarnings.length >= 1, JSON.stringify(c.build.findings));
    const pre = await (await handleConflicts(packId, req({ serverId: "s1" }), w.deps)).json();
    assert.equal(pre.installable, true);
    assert.ok(pre.requiredAcks.includes("restart"));
    const required: string[] = pre.requiredAcks;
    assert.ok(required.length >= 2, JSON.stringify(pre));
    assert.equal((await handleConflicts(packId, req({ serverId: "s9" }), w.deps)).status, 404, "another account's server");

    const partial = await handleInstall(packId, req({ serverId: "s1", acked: required.filter((a) => a !== required[0]) }), w.deps);
    assert.equal(partial.status, 409);
    assert.equal((await partial.json()).code, "needs_ack");
    assert.equal(w.m.jobs.length, 0, "nothing enqueued without every acknowledgement");

    const ok = await handleInstall(packId, req({ serverId: "s1", acked: required }, { "idempotency-key": "pack-install-1" }), w.deps);
