    const forged = { id: "jf", serverId: "s1", payload: { cyrusDelivery: { v: 1, op: "modpack_install", restartPolicy: "now", pack: { packId: c.pack.packId, versionId: "1.0.0", sha256: v.sha256 }, acknowledge: ["restart"] } } };
