// Wiring phase 2, item 2: Mod Pack routes (framework-free API, in-memory deps) over lib/cyrus/modpack, the worker
// payload expressing a pack op, and the install acknowledgement rule (EVERY open warning + the restart). The whole
// loop runs: create -> conflicts preview against the fake server -> install (refused until acknowledged) -> job ->
// the REAL job body -> deliverModPack -> files on the server -> status -> uninstall.
import "./_cyrus-server-only-shim";
import { describe, it, after } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { handleConflicts, handleCreate, handleGet, handleInstall, handleList, handleUninstall, handleValidate, type ModPackApiDeps } from "../lib/cyrus/modpack/api";
import { MemoryModPackStore, openPackArchive } from "../lib/cyrus/modpack/store";
import { membersFromBuild, memberIdFor } from "../lib/cyrus/modpack/members";
import { readDeliveryPayload } from "../lib/cyrus/delivery/request";
import { handleDeliveryStatus } from "../lib/cyrus/delivery/api";
import { runDeliveryJob } from "../lib/cyrus/delivery/job";
import { fsPlacer } from "../lib/cyrus/modpack/install";
import { scanServer } from "../lib/cyrus/inventory/scan";
import type { TxnFs } from "../lib/cyrus/delivery/types";
import { FakeServer, pluginJar, seedServer } from "./_cyrus-delivery-fakehost";
import { MemPortal, makeBuild } from "./_cyrus-delivery-memqueue";

const DP = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-datapack/showcase.json"), "utf8"));
const ENV = { CYRUS_MODPACKS: "1", CYRUS_DELIVERY: "1", CYRUS_MODPACK_INSTALL_REAL: "1", CYRUS_MANAGED_PLUGINS_REAL: "1" };
const req = (body: unknown, headers: Record<string, string> = {}) => new Request("http://x/api/cyrus/modpacks/v1", { method: "POST", headers: { "content-type": "application/json", ...headers }, body: JSON.stringify(body) });
const PERM = "\npermissions:\n  shared.perm:\n    default: op\n";

function world() {
  const srv = new FakeServer();
  seedServer(srv);
  const m = new MemPortal();
  m.user = { id: "u1" };
  m.servers.set("s1", { id: "s1", userId: "u1", name: "My server", eligible: true });
  m.servers.set("s9", { id: "s9", userId: "u9", name: "Not mine", eligible: true });
  const mk = (id: string, name: string, ns: string, extra = "", dp = false, userId = "u1") => {
    const jar = pluginJar(name, extra);
    m.projects.set(`cp_${id}`, { id: `cp_${id}`, namespace: ns, userId, rootBuildId: id });
    m.addBuild(makeBuild({ id, userId, pluginName: name, jarName: `${name}-1.0.0.jar`, jar, mcVersion: "1.21.11", project: { id: `cp_${id}`, namespace: ns }, ...(dp ? { datapackSpec: DP } : {}) }), jar);
  };
