  mk("bB", "PackBeta", "nx_packbeta");
  mk("bC", "PackGamma", "nx_packgamm", PERM);
  mk("bX", "Foreign", "nx_foreign1", "", false, "u9");
  const store = new MemoryModPackStore();
  let n = 0;
  const deps: ModPackApiDeps = {
    env: ENV,
    currentUser: async () => m.user,
    rateLimit: () => ({ ok: true, retryAfterSec: 0 }),
    async members(uid, buildId) {
      const b = m.builds.get(buildId);
      if (!b || b.userId !== uid) return { ok: false, status: 404, error: `Mod ${buildId} was not found or is not finished.` };
      const proj = [...m.projects.values()].find((p) => p.rootBuildId === (b.rootBuildId ?? b.id)) ?? null;
