    async inventory(uid, sid) { if (m.servers.get(sid)?.userId !== uid) return null; return { inventory: await scanServer(srv.raw, { base: "/opt/mc" }), ownedPaths: [] }; },
    checkServer: m.apiDeps(ENV).checkServer,
    enqueue: m.apiDeps(ENV).enqueue,
