const enc = (o: unknown) => new TextEncoder().encode(JSON.stringify(o));

export type SubmitResult =
  | { ok: true; job: AssetJob; requestKey: string; request: MeshgenRequest }
  | { ok: false; code: "switched_off" | "scratch_off" | "invalid"; issues: SpecIssue[] };

/** Validate everything that can be validated before any compute is spent, store the request, enqueue the job. */
export async function submitMeshgen(input: MeshgenRequestInput, deps: { queue: JobQueue; store: ObjectStore; env?: Env; timeoutMs?: number }): Promise<SubmitResult> {
  const env = deps.env ?? process.env;
  if (!meshgenEnabled(env)) return { ok: false, code: "switched_off", issues: [{ path: "", code: "switched_off", message: "AI mesh is switched off (CYRUS_MESHGEN)" }] };
  const r = MeshgenRequestZ.safeParse(input);
  if (!r.success) return { ok: false, code: "invalid", issues: zodIssues(r.error, "request") };
  let req = r.data;
  if (req.rung === "template" || req.rung === "kit") {
    const c = checkSpec(req.rung, req.rung === "template" ? req.template : null, req.spec);
    if (!c.ok) return { ok: false, code: "invalid", issues: c.issues };
    req = { ...req, spec: c.spec };
  } else {
    if (!scratchEnabled(env)) return { ok: false, code: "scratch_off", issues: [{ path: "rung", code: "scratch_off", message: "from-scratch scripts are switched off (CYRUS_MESHGEN_SCRATCH)" }] };
    const s = scanScratchScript(req.script);
    if (s.length) return { ok: false, code: "invalid", issues: s.slice(0, 20).map((i) => ({ path: `script:${i.line}`, code: `scan_${i.code}`, message: i.message })) };
  }
  const requestKey = await deps.store.put(enc(req));
  const job = await deps.queue.enqueue({ type: MESHGEN_JOB_TYPE, workerClass: "linux-cpu", projectId: req.projectId, inputs: [requestKey], timeoutMs: deps.timeoutMs ?? MESHGEN_TIMEOUT_MS[req.rung] });
  return { ok: true, job, requestKey, request: req };
}

/** The request.json the Blender harness reads. */
export function harnessRequestFor(req: MeshgenRequest): Record<string, unknown> {
  const common = { v: 1, name: req.assetId, rung: req.rung, budget: { maxTriangles: req.budget.maxTriangles, decimate: req.budget.decimate }, render: req.render ? { samples: req.render.samples } : null };
  if (req.rung === "template") return { ...common, template: req.template, spec: req.spec };
  if (req.rung === "kit") return { ...common, kit: req.kit, spec: req.spec };
  return { ...common, script: "scratch.py" };
}

