// Wiring phase 2: DURABLE file-backed implementations of the asset job contract (./asset-jobs.ts) for the first
// single-box lane: the web process enqueues and reads, the worker process claims and runs (meshgen today). Same
// semantics as the in-memory versions (tested against the same expectations). Layout under `root`:
//   objects/sha256/<hex>         content-addressed bytes (immutable; written by rename)
//   jobs/<id>.json               one job, rewritten atomically on every state change
//   jobs/<id>.claim              created with O_EXCL by the ONE worker that claims the job (the claim lock)
// Pure Node fs, no Nxeon import (host seam). Not for several hosts at once (a shared database queue replaces it then).
import { randomBytes } from "node:crypto";
import { mkdir, readFile, readdir, rename, rm, stat, writeFile, open } from "node:fs/promises";
import path from "node:path";
import { WORKER_CLASSES } from "../adapters/asset-profile";
import { contentKey, MAX_JOB_TIMEOUT_MS, type AssetJob, type JobQueue, type ObjectStore } from "./asset-jobs";

const KEY_RE = /^sha256\/[0-9a-f]{64}$/;
const JOB_RE = /^aj_[0-9a-z]{20}$/;

async function atomicWrite(file: string, data: Uint8Array | string) {
  await mkdir(path.dirname(file), { recursive: true, mode: 0o750 });
  const tmp = `${file}.${process.pid}.${randomBytes(4).toString("hex")}.part`;
  await writeFile(tmp, data, { mode: 0o640 });
  await rename(tmp, file);
}

export function createFsObjectStore(root: string): ObjectStore {
  const fileOf = (key: string) => { if (!KEY_RE.test(key)) throw new Error("bad object key"); return path.join(root, "objects", key); };
  return {
    async put(bytes) { const k = contentKey(bytes); const f = fileOf(k); try { await stat(f); } catch { await atomicWrite(f, bytes); } return k; },
    async get(key) { if (!KEY_RE.test(key)) return null; try { return new Uint8Array(await readFile(fileOf(key))); } catch { return null; } },
    async has(key) { if (!KEY_RE.test(key)) return false; try { await stat(fileOf(key)); return true; } catch { return false; } },
    async delete(key) { if (!KEY_RE.test(key)) return; await rm(fileOf(key), { force: true }); },
  };
}

export function createFsJobQueue(root: string, now: () => number = Date.now): JobQueue {
  const dir = path.join(root, "jobs");
  const fileOf = (id: string) => { if (!JOB_RE.test(id)) throw new Error("bad job id"); return path.join(dir, `${id}.json`); };
  const read = async (id: string): Promise<AssetJob | null> => { if (!JOB_RE.test(id)) return null; try { return JSON.parse(await readFile(fileOf(id), "utf8")) as AssetJob; } catch { return null; } };
  const write = (j: AssetJob) => atomicWrite(fileOf(j.id), JSON.stringify(j));
  const all = async (): Promise<AssetJob[]> => {
    let names: string[] = [];
    try { names = await readdir(dir); } catch { return []; }
    const jobs = await Promise.all(names.filter((n) => n.endsWith(".json")).map((n) => read(n.slice(0, -5))));
