// Cyrus meshgen (wiring phase 2): the HTTP layer behind app/api/cyrus/meshgen/v1/** (framework-free, deps injected).
//   POST /api/cyrus/meshgen/v1/estimate   { projectId, prompt, category?, forceRung? }  router decision + cost estimate
//   POST /api/cyrus/meshgen/v1/jobs       { projectId, request, acceptEstimate: { rung, totalTokens } }  -> queued job
//   GET  /api/cyrus/meshgen/v1/jobs/<id>  the job, its record, and (accepted) the asset it added to the project
// OFF unless CYRUS_MESHGEN=1 (404). Every path: signed-in Cyrus user, the project is the caller's own (404 otherwise),
// rate limited. The cost estimate is shown BEFORE anything runs: a job is refused (409 needs_estimate_ack) unless the
// request repeats the rung and token total the server computes for it now. Scratch scripts also need
// CYRUS_MESHGEN_SCRATCH=1 (submitMeshgen). No model is called here: the spec/script is in the request; the work is a
// Blender run on node-2 by the worker loop (one job at a time). An accepted mesh is recorded into the project's asset
// flow (a new "asset" revision + a model asset row) exactly once, when its owner reads the finished job.
import { routeMesh, type RouteDecision } from "./router";
import { estimateCost, type MeshgenPrices } from "./cost";
import { meshgenEnabled, submitMeshgen } from "./worker";
import { MESH_CATEGORIES, RUNGS, type MeshCategory, type Rung } from "./spec";
import { RECORD_KIND, type MeshgenRecord } from "./output";
import type { JobQueue, ObjectStore } from "../jobs/asset-jobs";

type Env = Record<string, string | undefined>;
export type MeshProject = { id: string; game: string };
export type IngestResult = { assetId: string; revisionId: string | null; already: boolean };
export type MeshgenApiDeps = {
  env: Env;
  currentUser(): Promise<{ id: string } | null>;
  rateLimit(key: string, max: number, windowMs: number): { ok: boolean; retryAfterSec: number };
  /** The caller's OWN project, or null. */
  project(userId: string, projectId: string): Promise<MeshProject | null>;
  prices(): Promise<MeshgenPrices | null>;
  queue: JobQueue;
  store: ObjectStore;
  /** Put an accepted mesh into the project's asset flow (idempotent by sha256). */
  ingest(a: { project: MeshProject; record: MeshgenRecord; glb: Uint8Array }): Promise<IngestResult>;
};

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "x-robots-tag": "noindex" } });
const NOT_FOUND = () => json(404, { error: "Not found" });
const ID = /^[A-Za-z0-9_-]{1,64}$/;
/** OWNER: tune. Per account. */
export const MESHGEN_RATE_LIMITS: [string, number, number][] = [["cyrus:meshgen:min", 6, 60_000], ["cyrus:meshgen:day", 60, 86_400_000]];

async function gate(d: MeshgenApiDeps, rl = MESHGEN_RATE_LIMITS): Promise<{ ok: true; uid: string } | { ok: false; res: Response }> {
  if (!meshgenEnabled(d.env)) return { ok: false, res: NOT_FOUND() };
  const user = await d.currentUser().catch(() => null);
  if (!user) return { ok: false, res: NOT_FOUND() };
  for (const [k, max, win] of rl) {
    const r = d.rateLimit(`${k}:${user.id}`, max, win);
    if (!r.ok) return { ok: false, res: json(429, { error: `Too many requests. Retry in ${r.retryAfterSec}s.`, code: "rate_limited" }) };
  }
  return { ok: true, uid: user.id };
}

const decisionView = (r: RouteDecision) => (r.ok
  ? { ok: true, rung: r.rung, templateId: r.templateId, reason: r.reason, considered: r.considered, warnings: r.warnings, estimate: r.estimate, candidates: r.candidates.slice(0, 5) }
  : { ok: false, code: r.code, reason: r.reason, considered: r.considered, warnings: r.warnings });

/** POST /estimate: which rung would make this, and what it costs - before anything runs. */
export async function handleEstimate(req: Request, d: MeshgenApiDeps): Promise<Response> {
  const g = await gate(d, [["cyrus:meshgen:estimate", 30, 60_000]]);
  if (!g.ok) return g.res;
  const b = (await req.json().catch(() => null)) as Record<string, unknown> | null;
  const projectId = typeof b?.projectId === "string" && ID.test(b.projectId) ? b.projectId : null;
  const prompt = typeof b?.prompt === "string" ? b.prompt.trim().slice(0, 2000) : "";
  if (!projectId || !prompt) return json(400, { error: "Send projectId and a prompt.", code: "bad_body" });
  const category = typeof b?.category === "string" && (MESH_CATEGORIES as readonly string[]).includes(b.category) ? (b.category as MeshCategory) : undefined;
  const forceRung = typeof b?.forceRung === "string" && (RUNGS as readonly string[]).includes(b.forceRung) ? (b.forceRung as Rung) : undefined;
  const project = await d.project(g.uid, projectId);
  if (!project) return NOT_FOUND();
  const scratch = d.env.CYRUS_MESHGEN_SCRATCH === "1" || d.env.CYRUS_MESHGEN_SCRATCH === "true";
  const r = await routeMesh({ prompt, game: project.game, category, forceRung, prices: await d.prices(), availability: { scratch } });
  return json(200, { decision: decisionView(r) });
}

/** POST /jobs: queue one mesh job, only after the caller accepted the estimate the server computes now. */
export async function handleSubmit(req: Request, d: MeshgenApiDeps): Promise<Response> {
  const g = await gate(d);
  if (!g.ok) return g.res;
  const b = (await req.json().catch(() => null)) as Record<string, unknown> | null;
  const projectId = typeof b?.projectId === "string" && ID.test(b.projectId) ? b.projectId : null;
  const request = b?.request && typeof b.request === "object" && !Array.isArray(b.request) ? (b.request as Record<string, unknown>) : null;
  if (!projectId || !request) return json(400, { error: "Send projectId and a mesh request.", code: "bad_body" });
  const project = await d.project(g.uid, projectId);
  if (!project) return NOT_FOUND();
  const rung = request.rung;
  if (rung !== "template" && rung !== "kit" && rung !== "scratch") return json(400, { error: "request.rung must be template, kit or scratch.", code: "bad_rung" });
  const est = estimateCost(rung, { prices: await d.prices() });
  const acc = b?.acceptEstimate && typeof b.acceptEstimate === "object" ? (b.acceptEstimate as Record<string, unknown>) : null;
  if (!acc || acc.rung !== rung || acc.totalTokens !== est.expected.totalTokens) return json(409, { error: "Confirm the cost estimate first.", code: "needs_estimate_ack", estimate: est });
  // the project, game and estimate are the server's, never the client's
  const r = await submitMeshgen({ ...(request as never), v: 1, projectId: project.id, game: project.game, estimate: { totalTokens: est.expected.totalTokens, dollars: est.dollars } }, { queue: d.queue, store: d.store, env: d.env });
  if (!r.ok) return json(r.code === "invalid" ? 422 : 409, { error: r.issues[0]?.message ?? "refused", code: r.code, issues: r.issues.slice(0, 20) });
  return json(202, { jobId: r.job.id, status: r.job.status, estimate: est });
}

/** GET /jobs/<id>: the job and its record; an accepted mesh lands in the project's assets on the first read. */
export async function handleJob(jobId: string, d: MeshgenApiDeps): Promise<Response> {
  const g = await gate(d, [["cyrus:meshgen:status", 120, 60_000]]);
  if (!g.ok) return g.res;
  const job = await d.queue.get(jobId).catch(() => null);
  if (!job) return NOT_FOUND();
  const project = await d.project(g.uid, job.projectId);
  if (!project) return NOT_FOUND();
  let record: MeshgenRecord | null = null;
  for (const k of job.outputs) {
    const raw = await d.store.get(k);
    if (!raw) continue;
    try { const j = JSON.parse(new TextDecoder().decode(raw)) as MeshgenRecord; if (j?.kind === RECORD_KIND && j.jobId === job.id) { record = j; break; } } catch { /* not the record */ }
  }
  let asset: IngestResult | null = null;
  let ingestError: string | null = null;
  if (job.status === "done" && record?.verdict === "accepted" && record.outputs.glb) {
    const glb = await d.store.get(record.outputs.glb);
    if (!glb) ingestError = "the mesh file is missing from the store";
    else { try { asset = await d.ingest({ project, record, glb }); } catch (e) { ingestError = (e as Error).message.slice(0, 300); } }
  }
  return json(200, {
    job: { id: job.id, status: job.status, error: job.error ?? null },
    record: record ? { verdict: record.verdict, notRunReason: record.notRunReason ?? null, rung: record.rung, module: record.module, issues: record.issues.slice(0, 20), stats: record.stats, decimated: record.decimated, tokens: record.tokens, compute: { wallMs: record.compute.wallMs, blenderSeconds: record.compute.blenderSeconds }, outputs: { glb: !!record.outputs.glb, renders: record.outputs.renders.length } } : null,
    asset, ingestError,
  });
}

