// Cyrus engine core: the project + revision store and the identifier registry (DB half). SERVER ONLY.
// The only writer of CyrusProject / CyrusRevision / CyrusProjectAsset / CyrusIdentifier.
// Rules: revisions are append-only (no function here edits or deletes their content); a revision's status moves
// once, pending -> passed | failed; a project always records its last passing revision; a revert is a NEW revision
// that copies an older one's content. Appends lock the project row (FOR UPDATE), so seq has no gaps and two writers
// cannot both build on the same head.
import { randomBytes } from "node:crypto";
import { Prisma, type CyrusIdentifier, type CyrusProject, type CyrusRevision } from "@prisma/client";
import { cyrusDb as db } from "../db";
import { getAdapter } from "../adapters";
import { validateModSpec, GAME_ID_RE, type ModSpec, type SpecIssue } from "./spec";
import { diffManifests, validateEngineRecord, validateManifest, REVISION_KINDS, type EngineRecord, type ManifestDiff, type ManifestEntry, type RevisionKind, type RevisionStatus } from "./revisions";
import { buildIdentifier, glyphBlockStart, glyphHomeBlock, GLYPH_BLOCK, GLYPH_BLOCKS, namespaceFromSeed, type IdentifierKind } from "./identifiers";

      if (!current || current.seq < rev.seq) await tx.cyrusProject.update({ where: { id: rev.projectId }, data: { lastPassingRevisionId: rev.id } });
    }
    return { ...rev, status };
  }, TX);
}

export async function getHead(projectId: string): Promise<CyrusRevision | null> {
  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { headRevisionId: true } });
  return p?.headRevisionId ? db.cyrusRevision.findUnique({ where: { id: p.headRevisionId } }) : null;
}

export async function lastPassing(projectId: string): Promise<CyrusRevision | null> {
  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { lastPassingRevisionId: true } });
  return p?.lastPassingRevisionId ? db.cyrusRevision.findUnique({ where: { id: p.lastPassingRevisionId } }) : null;
}

export async function recordAsset(projectId: string, a: RecordAssetInput) {
  if (!/^[0-9a-f]{64}$/.test(a.sha256)) throw new EngineStoreError("bad_input", "sha256 must be 64 lowercase hex characters");
  const rev = await getRevision(a.revisionId);
  if (!rev || rev.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const where = { projectId_kind_assetKey_sha256: { projectId, kind: a.kind, assetKey: a.assetKey, sha256: a.sha256 } };
  try {
    return await db.cyrusProjectAsset.create({
      data: { projectId, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ? (a.provenance as Prisma.InputJsonValue) : Prisma.DbNull },
    });
  } catch (e) {
    if (isUniqueViolation(e)) { const row = await db.cyrusProjectAsset.findUnique({ where }); if (row) return row; }
    throw e;
  }
}
export const listProjectAssets = (projectId: string) => db.cyrusProjectAsset.findMany({ where: { projectId }, orderBy: { createdAt: "asc" } });

