cd /tank/dev-worktrees/cyrus-r29 && cat > lib/cyrus/meshgen/queue.ts <<'EOF'
// Cyrus meshgen (wiring phase 2): the durable queue + object store the web route and the worker loop share
// (file-backed, lib/cyrus/jobs/fs-jobs.ts) and the worker tick. Root: CYRUS_MESHGEN_QUEUE_DIR, default
// NXEON_MODBUILD_DIR/meshgen (same host for web and worker). The tick is inert unless CYRUS_MESHGEN=1, runs at most ONE
// job per call and never two at once in a process; the Blender run itself happens on node-2 (runner.ts, its own lock).
import path from "node:path";
import { cyrusConfig } from "../config";
import { createFsJobQueue, createFsObjectStore } from "../jobs/fs-jobs";
import type { JobQueue, ObjectStore } from "../jobs/asset-jobs";
import { meshgenEnabled } from "./worker";

type Env = Record<string, string | undefined>;
export const meshgenQueueRoot = (env: Env = process.env) => env.CYRUS_MESHGEN_QUEUE_DIR || path.join(cyrusConfig(env).modbuildDir, "meshgen");
export function meshgenQueue(env: Env = process.env): { queue: JobQueue; store: ObjectStore } {
  const root = meshgenQueueRoot(env);
  return { queue: createFsJobQueue(root), store: createFsObjectStore(root) };
}

let busy = false;
/** One worker tick (scheduler): claim + run at most one meshgen job. */
export async function meshgenTick(env: Env = process.env): Promise<unknown> {
  if (!meshgenEnabled(env)) return { skipped: "switched off" };
  if (busy) return { skipped: "a mesh job is already running in this worker" };
  busy = true;
  try {
    const { runMeshgenWorker } = await import("./worker");
    const { createNode2BlenderRunner } = await import("./runner");
    const { queue, store } = meshgenQueue(env);
    return await runMeshgenWorker({ queue, store, runner: createNode2BlenderRunner(), workerId: `worker-${process.pid}`, env }, { maxJobs: 1, idleMs: 0 });
  } finally { busy = false; }
}
