// Test helpers for the Cyrus meshgen suites: a tiny valid GLB builder and a fake harness result.
import type { HarnessResult } from "../lib/cyrus/meshgen/checks";
const MAGIC = 0x46546c67, JSON_CHUNK = 0x4e4f534a, BIN_CHUNK = 0x004e4942;

/** Smallest valid GLB with one triangle (for tests and fakes). */
export function tinyGlb(opts: { triangles?: number; materials?: number; extraJson?: Record<string, unknown> } = {}): Uint8Array {
  const tris = opts.triangles ?? 1;
  const pos = new Float32Array(tris * 9);
  for (let t = 0; t < tris; t++) pos.set([t, 0, 0, t + 1, 0, 0, t, 1, 0], t * 9);
  const binLen = Math.ceil(pos.byteLength / 4) * 4;
  const mats = Array.from({ length: opts.materials ?? 1 }, (_, i) => ({ name: `m${i}` }));
  const doc = {
    asset: { version: "2.0", generator: "cyrus-meshgen-test" }, scene: 0, scenes: [{ nodes: [0] }], nodes: [{ mesh: 0 }],
    meshes: [{ primitives: [{ attributes: { POSITION: 0 }, material: 0 }] }], materials: mats,
    buffers: [{ byteLength: pos.byteLength }], bufferViews: [{ buffer: 0, byteLength: pos.byteLength }],
    accessors: [{ bufferView: 0, componentType: 5126, count: tris * 3, type: "VEC3", min: [0, 0, 0], max: [tris, 1, 0] }],
    ...opts.extraJson,
  };
  let js = Buffer.from(JSON.stringify(doc), "utf8");
  if (js.length % 4) js = Buffer.concat([js, Buffer.alloc(4 - (js.length % 4), 0x20)]);
  const total = 12 + 8 + js.length + 8 + binLen;
  const out = Buffer.alloc(total);
  out.writeUInt32LE(MAGIC, 0); out.writeUInt32LE(2, 4); out.writeUInt32LE(total, 8);
  out.writeUInt32LE(js.length, 12); out.writeUInt32LE(JSON_CHUNK, 16); js.copy(out, 20);
  const b = 20 + js.length;
  out.writeUInt32LE(binLen, b); out.writeUInt32LE(BIN_CHUNK, b + 4); Buffer.from(pos.buffer).copy(out, b + 8);
  return new Uint8Array(out);
}

/** A harness result.json for a clean build of `tris` triangles in one object (matches tinyGlb({ triangles })). */
export function fakeResult(o: { tris?: number; name?: string; nonmanifold?: number; uv?: boolean; materials?: number; reimport?: number; bbox?: [number, number, number] } = {}): HarnessResult {
  const tris = o.tris ?? 1, name = o.name ?? "asset";
  const per = [{ name: "obj0", tris, nonmanifold_edges: o.nonmanifold ?? 0, shells: 1, uv: o.uv ?? true, uv_out_of_bounds: 0, degenerate_faces: 0, loose_verts: 0, materials: 1, bbox_m: o.bbox ?? [0.5, 0.3, 0.3] }];
  return {
    v: 1, harness: 1, ok: true, blender: "5.2.2 LTS", name, rung: "template", timings: { total_s: 1.5 }, decimated: null,
    stats: { objects: 1, tris, nonmanifold_edges: o.nonmanifold ?? 0, uv_objs: 1, shells: 1, degenerate_faces: 0, materials: o.materials ?? 1, bbox_m: o.bbox ?? [0.5, 0.3, 0.3], per_obj: per },
    glb: { file: `${name}.glb`, bytes: 0, reimport_meshes: 1, reimport_tris: o.reimport ?? tris },
    renders: [`${name}_v0.png`], sheet: `${name}_sheet.png`,
  };
}
