      r.calls++; r.last = job; o.onRun?.();
      if (o.throws) throw new Error("ssh exploded");
      const name = String(job.harnessRequest.name);
      const files = new Map<string, Uint8Array>([[`${name}_v0.png`, new Uint8Array([1, 2, 3])], [`${name}_sheet.png`, new Uint8Array([4, 5])]]);
