const tmp = () => { const d = mkdtempSync(path.join(tmpdir(), "cyrus-w2-")); tmps.push(d); return d; };
const post = (body: unknown, headers: Record<string, string> = {}) => new Request("http://x/", { method: "POST", headers: { "content-type": "application/json", ...headers }, body: typeof body === "string" ? body : JSON.stringify(body) });

