const SPEC: ModSpec = (() => { const v = validateModSpec(JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-playtest/tfplay.modspec.json"), "utf8")), { adapterFor: getAdapter }); assert.ok(v.ok); return (v as { spec: ModSpec }).spec; })();
const BUILD: GateBuild = { id: "b1", mcVersion: "1.21.11", pluginName: "TfPlay", jarSha256: "a".repeat(64), result: { safety: { verdict: "pass" } } };
const checks = (over: Record<string, Partial<CheckResult>> = {}): CheckResult[] => CHECK_IDS.map((id) => ({ id, status: "pass", required: true, evidence: [`${id} ok`], durationMs: 1, ...(over[id] ?? {}) }) as CheckResult);
const ptRun = (status: "pass" | "fail"): PlaytestRunResult => {
  const plan = planFromSpec(SPEC).plan!;
  return { schema: 1, username: "NxPlaytest", version: "1.21.11", joined: true, joinFailed: false, joinMs: 900, op: false, bot: { mineflayer: "4", minecraftProtocol: "1", lockSha256: "x" }, notes: [], disconnect: null,
    scenarios: plan.scenarios.map((s, i) => ({ id: s.id, title: null, covers: s.covers ?? [], status: i === 0 ? status : "pass", ms: 1, steps: [{ i: 0, kind: "command", status: "pass", evidence: ["sent"], ms: 1 }, { i: 1, kind: "expect_chat", status: i === 0 ? status : "pass", evidence: ["seen"], ms: 1 }] })) };
};
const report = (pt: PlaytestRunResult | null, playtestCheck: "pass" | "fail" = "pass"): TestFlightReport => ({
  schema: 1, runId: "tf-x", status: "completed", version: "1.21.11", javaRelease: 21, startedAt: "", finishedAt: "", checks: checks({ playtest: { status: pt ? playtestCheck : "not_run", evidence: pt ? ["ran"] : [] } }), timings: {},
  bootMs: 1, doneReportedSec: 1, peakRssKb: 1, artifacts: [], engine: null, notes: [], overall: "passed", ...(pt ? { playtest: pt } : {}),
});
function gateDeps(env: Record<string, string>, spec: ModSpec | null, rep: (s: TestFlightSpec) => TestFlightReport, store: Map<string, StoredFlight>): GateDeps & { flown: TestFlightSpec[] } {
  const d = {
    flown: [] as TestFlightSpec[], env, now: () => new Date("2026-10-10T12:00:00Z"),
    async candidates() { return []; },
    async artifacts() { return { jarPath: "/tmp/x.jar", datapacks: [] }; },
    async run(s: TestFlightSpec) { d.flown.push(s); const r = rep(s); return { report: r, summary: summarize(s, r), resolved: {} as never, stderr: "" }; },
    async store(id: string, f: StoredFlight) { store.set(id, JSON.parse(JSON.stringify(f))); },
    async spec() { return spec ? { spec, revisionId: "rev_1" } : null; },
  };
  return d;
}

describe("Test Flight gate -> playtest bots (CYRUS_PLAYTEST)", () => {
  const G = { CYRUS_TESTFLIGHT_GATE: "1" };
  it("off: the flight carries no playtest and nothing is stored about it (behaviour-neutral)", async () => {
    const st = new Map<string, StoredFlight>();
    const d = gateDeps(G, SPEC, () => report(null), st);
    await flyOne(BUILD, null, d, d.now);
    assert.equal(d.flown[0].playtest, undefined);
    assert.equal("playtest" in st.get("b1")!, false);
    assert.equal(st.get("b1")!.verdict, "passed");
  });
  it("on + stored ModSpec: ONE flight with the plan; a passing playtest is recorded apart", async () => {
    const st = new Map<string, StoredFlight>();
    const d = gateDeps({ ...G, CYRUS_PLAYTEST: "1" }, SPEC, () => report(ptRun("pass")), st);
    await flyOne(BUILD, null, d, d.now);
    assert.equal(d.flown.length, 1); assert.ok(d.flown[0].playtest);
    const f = st.get("b1")!;
    assert.equal(f.verdict, "passed"); assert.equal(f.playtest!.verdict, "passed"); assert.equal(f.playtest!.specRevisionId, "rev_1");
  });
  it("a failing playtest never changes the boot verdict (and so never blocks install by itself)", async () => {
    const st = new Map<string, StoredFlight>();
    const d = gateDeps({ ...G, CYRUS_PLAYTEST: "1" }, SPEC, () => report(ptRun("fail"), "fail"), st);
    await flyOne(BUILD, null, d, d.now);
    const f = st.get("b1")!;
    assert.equal(f.playtest!.verdict, "failed"); assert.equal(f.verdict, "passed"); assert.equal(f.label, "boot-tested on Paper 1.21.11");
  });
  it("no stored spec / a version mismatch: not run, the boot flight is unchanged", async () => {
    const st = new Map<string, StoredFlight>();
    const d = gateDeps({ ...G, CYRUS_PLAYTEST: "1" }, null, () => report(null), st);
    await flyOne(BUILD, null, d, d.now);
    assert.equal(d.flown[0].playtest, undefined);
    assert.deepEqual(st.get("b1")!.playtest, { verdict: "not_run", label: "not run: this build has no stored ModSpec", specRevisionId: null });
    const st2 = new Map<string, StoredFlight>();
    const d2 = gateDeps({ ...G, CYRUS_PLAYTEST: "1" }, { ...SPEC, target: { ...SPEC.target, version: "1.21.10" } }, () => report(null), st2);
    await flyOne(BUILD, null, d2, d2.now);
    assert.match(st2.get("b1")!.playtest!.label, /targets 1\.21\.10/);
  });
});

