describe("Server Doctor admin API (read-only)", () => {
  const srv = new FakeServer(); seedServer(srv);
  after(() => srv.cleanup());
  const deps = (o: Partial<DoctorApiDeps> = {}): DoctorApiDeps & { audits: string[] } => {
    const audits: string[] = [];
