      openReadOnly: async (u, s) => (u === "u1" && s === "s1" ? { fs: srv.raw, base: "/opt/mc" } : null), audit: async (_a, d) => { audits.push(d); }, now: () => new Date("2026-10-10T12:00:00Z"), ...o };
  };
  it("off / not an admin / not that account's server: 404, nothing read", async () => {
    assert.equal((await handleAdminDoctor(post({ userId: "u1", serverId: "s1" }), deps({ env: {} }))).status, 404);
    assert.equal((await handleAdminDoctor(post({ userId: "u1", serverId: "s1" }), deps({ admin: async () => null }))).status, 404);
    assert.equal((await handleAdminDoctor(post({ userId: "u2", serverId: "s1" }), deps())).status, 404);
    assert.equal((await handleAdminDoctor(post({ serverId: "s1" }), deps())).status, 400);
