    const before = srv.tree();
    const d = deps();
    const r = await handleAdminDoctor(post({ userId: "u1", serverId: "s1" }), d);
    assert.equal(r.status, 200);
    const b = await r.json();
    assert.equal(b.report.readOnly, true); assert.ok(b.report.installed.some((p: { name: string }) => p.name === "Unrelated"));
    assert.match(b.text, /Server Doctor|Doctor/i);
    assert.equal(d.audits.length, 1);
    assert.equal(srv.tree(), before);
    const v = readOnlyView(new LocalGuestFs(srv.dir)) as unknown as Record<string, unknown>;
