  });
});

// ------------------------------------------------------------------------------------------------ telemetry ingest
describe("telemetry ingest (HMAC, strict, draft storage)", () => {
  const SECRET = "s".repeat(32);
  const ON = { CYRUS_HEALTH_TELEMETRY: "1", CYRUS_HEALTH_TELEMETRY_SECRET: SECRET };
  const NOW = new Date("2026-10-10T12:00:00Z");
  const sig: HealthSignal = { v: 1, day: "2026-10-10", serverKey: "a".repeat(32), window: Math.floor(Math.floor(NOW.getTime() / 86400000) / 30), buildId: "build_abc123", mcVersion: "1.21.11", software: "paper", event: "boot_ok", count: 3 };
  const store = (available: boolean): SignalStore & { got: HealthSignal[] } => { const got: HealthSignal[] = []; return { got, available: async () => available, upsert: async (s) => { got.push(...s); return s.length; } }; };
  const send = (body: unknown, st: SignalStore, env: Record<string, string> = ON, badSig = false) => { const raw = JSON.stringify(body); return handleTelemetryIngest(post(raw, { [SIGNATURE_HEADER]: badSig ? "0".repeat(64) : signBody(SECRET, raw) }), { env, store: st, now: () => NOW }); };
  it("off or no secret: 404; bad signature: 401", async () => {
    assert.equal((await send({ signals: [sig] }, store(true), {})).status, 404);
    assert.equal((await send({ signals: [sig] }, store(true), { CYRUS_HEALTH_TELEMETRY: "1", CYRUS_HEALTH_TELEMETRY_SECRET: "short" })).status, 404);
    assert.equal((await send({ signals: [sig] }, store(true), ON, true)).status, 401);
  });
  it("one invalid signal (free text) refuses the whole batch; out-of-window days refused; nothing stored", async () => {
    const st = store(true);
    const bad = await send({ signals: [sig, { ...sig, playerName: "Steve" }] }, st);
    assert.equal(bad.status, 422);
    assert.equal((await send({ signals: [{ ...sig, day: "2026-08-01" }] }, st)).status, 422);
    assert.equal(st.got.length, 0);
  });
  it("draft tables absent: 503 and nothing stored; present: stored", async () => {
    const absent = store(false);
    const r = await send({ signals: [sig] }, absent);
    assert.equal(r.status, 503); assert.equal((await r.json()).code, "storage_absent"); assert.equal(absent.got.length, 0);
    const ok = store(true);
    assert.equal((await send({ signals: [sig] }, ok)).status, 200); assert.equal(ok.got.length, 1);
  });
});

