describe("meshgen route + durable queue + asset flow", () => {
  const ON = { CYRUS_MESHGEN: "1" };
  const budget = () => { const b = resolveBudget(DRAFT_MESH_PROFILE, "container"); assert.ok(b.ok); return b.budget; };
  const request = { v: 1, assetId: "crate_a", projectId: "IGNORED", game: "IGNORED", category: "container", prompt: "sci-fi crate", budget: budget(), rung: "template", template: "crate", spec: { style: "scifi" } };
  function world(env: Record<string, string> = ON) {
    const root = tmp();
    const queue = createFsJobQueue(root), store = createFsObjectStore(root);
    const assets: { id: string; revisionId: string; projectId: string; assetKey: string; sha256: string }[] = [];
    const revs: { id: string; manifest: { path: string; sha256: string; role: "asset" }[] }[] = [];
    const ing: IngestDeps = {
      findAsset: async (p, k, s) => assets.find((a) => a.projectId === p && a.assetKey === k && a.sha256 === s) ?? null,
      head: async () => revs[revs.length - 1] ?? null,
      addRevision: async (_p, input) => { const r = { id: `rev_${revs.length + 1}`, manifest: input.manifest as never }; revs.push(r); return r; },
      recordAsset: async (p, a) => { const row = { id: `asset_${assets.length + 1}`, revisionId: a.revisionId, projectId: p, assetKey: a.assetKey, sha256: a.sha256 }; assets.push(row); return row; },
    };
    let user: { id: string } | null = { id: "u1" };
    const deps: MeshgenApiDeps = {
      env, currentUser: async () => user, rateLimit: () => ({ ok: true, retryAfterSec: 0 }),
      project: async (u, id) => (u === "u1" && id === "cp1" ? { id: "cp1", game: "gltf-prop-draft" } : null),
      prices: async () => null, queue, store,
      ingest: (a) => ingestMeshRecord(ing, a),
    };
    return { root, queue, store, deps, assets, revs, setUser: (u: { id: string } | null) => { user = u; } };
  }
  const runner = (): BlenderRunner => ({ id: "fake", async run(job): Promise<BlenderRun> {
    const name = String(job.harnessRequest.name);
    const files = new Map<string, Uint8Array>([[`${name}_v0.png`, new Uint8Array([1])], [`${name}_sheet.png`, new Uint8Array([2])], [`${name}.glb`, tinyGlb({ triangles: 4 })]]);
    return { status: "ok", exitCode: 0, result: fakeResult({ tris: 4, name }), files, logTail: "", wallMs: 1, lockWaitMs: 0, totalMs: 1, filesSha256: "f".repeat(64), runner: "fake" };
  } });

  it("off: 404 on every route", async () => {
    const w = world({});
    assert.equal((await handleEstimate(post({ projectId: "cp1", prompt: "crate" }), w.deps)).status, 404);
    assert.equal((await handleSubmit(post({ projectId: "cp1", request }), w.deps)).status, 404);
    assert.equal((await handleJob("aj_x", w.deps)).status, 404);
  });
  it("estimate first; a job without the estimate accepted is refused; someone else's project is 404", async () => {
    const w = world();
    const e = await (await handleEstimate(post({ projectId: "cp1", prompt: "a sci-fi supply crate", category: "container" }), w.deps)).json();
    assert.equal(e.decision.ok, true); assert.ok(e.decision.estimate.expected.totalTokens > 0);
    assert.equal((await handleEstimate(post({ projectId: "cp9", prompt: "crate" }), w.deps)).status, 404);
    const no = await handleSubmit(post({ projectId: "cp1", request }), w.deps);
    assert.equal(no.status, 409);
    const nb = await no.json();
    assert.equal(nb.code, "needs_estimate_ack");
    const wrong = await handleSubmit(post({ projectId: "cp1", request, acceptEstimate: { rung: "template", totalTokens: 1 } }), w.deps);
    assert.equal(wrong.status, 409);
    assert.equal((await w.queue.claim({ id: "w", classes: ["linux-cpu"] })), null, "nothing was queued");
  });
  it("accepted estimate -> durable job (project + game forced to the server's) -> worker -> accepted -> asset flow once", async () => {
    const w = world();
    const est = (await (await handleSubmit(post({ projectId: "cp1", request }), w.deps)).json()).estimate;
    const r = await handleSubmit(post({ projectId: "cp1", request, acceptEstimate: { rung: "template", totalTokens: est.expected.totalTokens } }), w.deps);
    assert.equal(r.status, 202);
    const { jobId } = await r.json();
    const job = (await w.queue.get(jobId))!;
    assert.equal(job.projectId, "cp1"); assert.equal(job.type, MESHGEN_JOB_TYPE);
    const queued = await (await handleJob(jobId, w.deps)).json();
    assert.equal(queued.job.status, "queued"); assert.equal(queued.asset, null);
    // a second, independent queue object over the same directory (the worker process) drains it
    const res = await runMeshgenWorker({ queue: createFsJobQueue(w.root), store: createFsObjectStore(w.root), runner: runner(), workerId: "w1", env: ON }, { maxJobs: 1 });
    assert.equal(res.accepted, 1);
    const done = await (await handleJob(jobId, w.deps)).json();
    assert.equal(done.job.status, "done"); assert.equal(done.record.verdict, "accepted");
    assert.equal(done.asset.already, false); assert.equal(w.assets.length, 1); assert.deepEqual(w.revs[0].manifest.map((m) => m.path), ["assets/models/crate_a.glb"]);
    const again = await (await handleJob(jobId, w.deps)).json();
    assert.equal(again.asset.already, true); assert.equal(w.assets.length, 1, "idempotent");
    w.setUser({ id: "u9" });
    assert.equal((await handleJob(jobId, w.deps)).status, 404, "another account cannot read the job");
  });
  it("fs queue: one claim per job across queue objects; expired jobs are swept", async () => {
    const root = tmp();
    let t = 1000;
    const a = createFsJobQueue(root, () => t), b = createFsJobQueue(root, () => t);
    const j = await a.enqueue({ type: MESHGEN_JOB_TYPE, workerClass: "linux-cpu", projectId: "p", inputs: [], timeoutMs: 50 });
    const [c1, c2] = await Promise.all([a.claim({ id: "w1", classes: ["linux-cpu"] }), b.claim({ id: "w2", classes: ["linux-cpu"] })]);
    assert.equal([c1, c2].filter(Boolean).length, 1);
    t += 100;
    assert.deepEqual((await b.sweep()).map((x) => x.id), [j.id]);
    assert.equal((await a.get(j.id))!.status, "expired");
    const s = createFsObjectStore(root);
    const k = await s.put(new Uint8Array([1, 2, 3]));
    assert.equal(k, `sha256/${createHash("sha256").update(new Uint8Array([1, 2, 3])).digest("hex")}`);
    assert.deepEqual([...(await s.get(k))!], [1, 2, 3]);
    assert.equal(await s.get("../../etc/passwd"), null);
  });
});

