    const d = gateDeps({ ...G, CYRUS_PLAYTEST: "1" }, null, () => report(null), st);
    await flyOne(BUILD, null, d, d.now);
    assert.equal(d.flown[0].playtest, undefined);
    assert.deepEqual(st.get("b1")!.playtest, { verdict: "not_run", label: "not run: this build has no stored ModSpec", specRevisionId: null });
    const st2 = new Map<string, StoredFlight>();
    const d2 = gateDeps({ ...G, CYRUS_PLAYTEST: "1" }, { ...SPEC, target: { ...SPEC.target, version: "1.21.10" } }, () => report(null), st2);
    await flyOne(BUILD, null, d2, d2.now);
    assert.match(st2.get("b1")!.playtest!.label, /targets 1\.21\.10/);
  });
});

